    function populateCategorySelects(selectedCat) {
      const select = document.getElementById("admProdCategory");
      if (!select) return;
      const cats = (MOCK_DATA && MOCK_DATA.categories) ? MOCK_DATA.categories : ["Gmail", "TikTok", "Facebook", "Telegram", "Proxy", "AI & Video"];
      const validCats = cats.filter(c => c !== "Tất cả").map(c => c.replace(/&amp;/g, '&'));
      const normSelected = selectedCat ? String(selectedCat).replace(/&amp;/g, '&').toLowerCase() : "";
      
      let html = "";
      validCats.forEach(c => {
        const isSel = (normSelected && normSelected === c.toLowerCase()) ? "selected" : "";
        html += '<option value="' + escapeHtml(c).replace(/&amp;/g, '&') + '" ' + isSel + '>' + escapeHtml(c) + '</option>';
      });
      if (selectedCat && selectedCat !== "Tất cả" && !validCats.some(c => c.toLowerCase() === normSelected)) {
        const cleanSel = String(selectedCat).replace(/&amp;/g, '&');
        html += '<option value="' + escapeHtml(cleanSel).replace(/&amp;/g, '&') + '" selected>' + escapeHtml(cleanSel) + '</option>';
      }
      select.innerHTML = html;
      if (selectedCat) select.value = String(selectedCat).replace(/&amp;/g, '&');
    }
    window.populateCategorySelects = populateCategorySelects;

    function toggleDeliveryTypeClick() {
      const radioLocal = document.getElementById("admProdTypeLocal");
      const radioApi = document.getElementById("admProdTypeApi");
      if (!radioLocal || !radioApi) return;
      if (radioLocal.checked) {
        radioLocal.checked = false;
        radioApi.checked = true;
      } else {
        radioLocal.checked = true;
        radioApi.checked = false;
      }
      toggleAdmProductSourceFields();
    }
    window.toggleDeliveryTypeClick = toggleDeliveryTypeClick;

    function autoDetectBestProviderForName(name) {
      if (!name || typeof name !== "string") return null;
      const raw = name.toLowerCase().trim();
      const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
      if (!prods.length) return null;

      let kw = "";
      if (raw.includes("gemini") || raw.includes("veo")) kw = "gemini";
      else if (raw.includes("chatgpt") || raw.includes("gpt") || raw.includes("openai")) kw = "chatgpt";
      else if (raw.includes("canva")) kw = "canva";
      else if (raw.includes("capcut")) kw = "capcut";
      else if (raw.includes("kling")) kw = "kling";
      else if (raw.includes("claude")) kw = "claude";
      else if (raw.includes("midjourney")) kw = "midjourney";
      else if (raw.includes("tiktok") || raw.includes("tik tok")) kw = "tiktok";
      else if (raw.includes("instagram") || raw.includes("ig")) kw = "instagram";
      else if (raw.includes("facebook") || raw.includes("fb") || raw.includes("via") || raw.includes("clone")) kw = "facebook";
      else if (raw.includes("gmail") || raw.includes("mail domain") || raw.includes("edu")) kw = "gmail";
      else if (raw.includes("hotmail") || raw.includes("outlook")) kw = "hotmail";
      else if (raw.includes("proxy") || raw.includes("socks") || raw.includes("ipv4")) kw = "proxy";
      else if (raw.includes("youtube") || raw.includes("ytb")) kw = "youtube";
      else if (raw.includes("discord")) kw = "discord";
      else if (raw.includes("telegram")) kw = "telegram";
      else kw = raw.split(/\s+/).filter(w => w.length >= 2).slice(0, 2).join(" ");

      if (!kw) return null;

      const counts = {};
      prods.forEach(p => {
        if (!p || !p.provider) return;
        const txt = ((p.name || "") + " " + (p.category || "")).toLowerCase();
        if (txt.includes(kw)) {
          counts[p.provider] = (counts[p.provider] || 0) + (p.amount > 0 ? 2 : 1);
        }
      });

      const sorted = Object.keys(counts).sort((a, b) => counts[b] - counts[a]);
      return sorted.length > 0 ? sorted[0] : null;
    }
    window.autoDetectBestProviderForName = autoDetectBestProviderForName;

    // =========================================================================
    // [KHOTAIKHOANSO LIVE CORE]: QUÉT SẠCH CARD SẢN PHẨM ĐÃ XÓA KHỎI DOM GIAO DIỆN
    // =========================================================================
    function purgeDeletedProductsFromDOM() {
      try {
        var hardcodedDeleted = (typeof GLOBAL_PERMANENT_DELETED_IDS !== "undefined" && Array.isArray(GLOBAL_PERMANENT_DELETED_IDS))
          ? GLOBAL_PERMANENT_DELETED_IDS
          : ["PROD_TEST"];
        var localDeleted = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
        var allDeleted = [...new Set(hardcodedDeleted.concat(localDeleted).map(function(x) { return String(x || "").trim().toLowerCase(); }))];
        if (!allDeleted || allDeleted.length === 0) return;
        var allCards = document.querySelectorAll(".product-card, .sponsor-card, .compact-item, .compact-product-item, tr");
        allCards.forEach(function(el) {
          var onclick = (el.getAttribute("onclick") || "").toLowerCase();
          var href = "";
          var a = el.querySelector("a");
          if (a) href = (a.getAttribute("href") || "").toLowerCase();
          var title = (el.getAttribute("title") || "").toLowerCase();
          var text = (el.innerText || "").toLowerCase();

          var shouldRemove = false;
          for (var i = 0; i < allDeleted.length; i++) {
            var d = allDeleted[i];
            if (!d || d.length < 3) continue;
            if (onclick.indexOf(d) !== -1 || href.indexOf(d) !== -1 || (title && title.indexOf(d) !== -1)) {
              shouldRemove = true;
              break;
            }
            if (d.startsWith("prod_") && text.indexOf(d) !== -1) {
              shouldRemove = true;
              break;
            }
          }
          if (shouldRemove) {
            el.remove();
          }
        });
      } catch(e) {}
    }
    window.purgeDeletedProductsFromDOM = purgeDeletedProductsFromDOM;

