    function renderAdmModalProviderOptions(activeProv) {
      var pSel = document.getElementById("admProdApiProvider");
      var pillsContainer = document.getElementById("admModalProviderPills");
      if (!pSel && !pillsContainer) return;

      if (typeof loadAndApplyCustomApiSources === "function") {
        try { loadAndApplyCustomApiSources(); } catch(e) {}
      }

      var allSources = [];
      var seenIds = {};

      var builtinDefs = [
        { id: "selltainguyenmmo", name: "selltainguyenmmo.com (1.600+ SP)", shortName: "selltainguyenmmo", icon: "fa-layer-group", color: "#8b5cf6" },
        { id: "ultrammo", name: "ultrammo.com (AI & Proxy)", shortName: "ultrammo", icon: "fa-globe", color: "#ec4899" },
        { id: "nguyenlieummo", name: "nguyenlieummo.com.vn (2.400+ SP)", shortName: "nguyenlieummo", icon: "fa-boxes-stacked", color: "#f59e0b" }
      ];
      builtinDefs.forEach(function(b) {
        allSources.push(b);
        seenIds[b.id] = true;
      });

      var customList = (typeof getCustomApiSources === "function") ? getCustomApiSources() : [];
      if (Array.isArray(customList)) {
        customList.forEach(function(cs) {
          if (cs && cs.id && !seenIds[cs.id]) {
            seenIds[cs.id] = true;
            var cColor = cs.badgeColor || "#06b6d4";
            var cName = cs.name || cs.id;
            allSources.push({
              id: cs.id,
              name: cName + " (" + (cs.baseUrl || "Custom API") + ")",
              shortName: cName,
              icon: "fa-plug",
              color: cColor,
              isCustom: true
            });
          }
        });
      }

      if (!activeProv) {
        activeProv = (pSel && pSel.value) ? pSel.value : "selltainguyenmmo";
      }

      // Cập nhật Dropdown Select
      if (pSel) {
        pSel.innerHTML = "";
        allSources.forEach(function(s, idx) {
          var opt = document.createElement("option");
          opt.value = s.id;
          opt.textContent = (idx + 1) + ". " + s.name;
          if (s.id === activeProv) opt.selected = true;
          pSel.appendChild(opt);
        });
        pSel.value = activeProv;
      }

      // Cập nhật Buttons Pills
      if (pillsContainer) {
        pillsContainer.innerHTML = "";
        allSources.forEach(function(s, idx) {
          var btn = document.createElement("button");
          btn.type = "button";
          var isActive = (s.id === activeProv);
          btn.className = "adm-prov-pill" + (isActive ? " active" : "");
          btn.setAttribute("data-prov", s.id);
          btn.onclick = function() { selectModalApiProvider(s.id); };

          btn.style.cssText = "padding:5px 9px; border-radius:6px; font-size:0.75rem; font-weight:700; cursor:pointer; display:inline-flex; align-items:center; gap:5px; transition:all 0.15s; " +
            (isActive
              ? "background:rgba(6,182,212,0.2); border:1px solid #06b6d4; color:#38bdf8; box-shadow:0 0 10px rgba(6,182,212,0.35);"
              : "background:#0d121f; border:1px solid rgba(255,255,255,0.1); color:#cbd5e1;");

          var iconClass = isActive ? "fa-solid fa-check" : ("fa-solid " + s.icon);
          btn.innerHTML = '<i class="' + iconClass + '"></i> ' + (idx + 1) + '. ' + s.shortName + (s.isCustom ? ' <span style="font-size:0.65rem; background:' + s.color + '30; color:' + s.color + '; padding:1px 4px; border-radius:3px;">Tự thêm</span>' : '');
          pillsContainer.appendChild(btn);
        });
      }

      // Cập nhật Badge hiển thị nhà cung cấp đang chọn
      var badge = document.getElementById("admModalActiveProvBadge");
      if (badge) {
        var found = allSources.find(function(s) { return s.id === activeProv; });
        var dispName = found ? found.shortName : activeProv;
        badge.innerHTML = 'Đang chọn: <strong style="color:#38bdf8;">' + dispName + '</strong>';
      }
    }
    window.renderAdmModalProviderOptions = renderAdmModalProviderOptions;

    function updateModalProviderPillsUI(activeProv) {
      renderAdmModalProviderOptions(activeProv);
    }
    window.updateModalProviderPillsUI = updateModalProviderPillsUI;

    function selectModalApiProvider(prov) {
      if (!prov) return;
      if (typeof renderAdmModalProviderOptions === "function") {
          renderAdmModalProviderOptions(prov);
        } else if (typeof updateModalProviderPillsUI === "function") {
          updateModalProviderPillsUI(prov);
        }
        const pSel = document.getElementById("admProdApiProvider");
        if (pSel) {
          pSel.value = prov;
        }
      handleAdmModalProviderChange();

      const curProds = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
      const inProv = curProds.filter(p => p.provider === prov);
      if (inProv.length <= 1 && typeof fetchSingleSourceProducts === "function") {
        fetchSingleSourceProducts(prov, false);
      }
    }
    window.selectModalApiProvider = selectModalApiProvider;

    function toggleAdmProductSourceFields() {
      const isApi = document.getElementById("admProdTypeApi")?.checked;
      const panel = document.getElementById("admProdApiConfigPanel");
      const badge = document.getElementById("admProdTypeBadge");
      if (panel) panel.style.display = isApi ? "block" : "none";
      if (badge) {
        if (isApi) {
          badge.innerHTML = '<i class="fa-solid fa-bolt"></i> Mua Qua API';
          badge.style.background = 'rgba(6,182,212,0.15)';
          badge.style.color = '#06b6d4';
          badge.style.borderColor = 'rgba(6,182,212,0.3)';
        } else {
          badge.innerHTML = '<i class="fa-solid fa-box"></i> Kho Nội Bộ';
          badge.style.background = 'rgba(16,185,129,0.15)';
          badge.style.color = '#10b981';
          badge.style.borderColor = 'rgba(16,185,129,0.3)';
        }
      }
      if (isApi) {
        const isEditing = !!(document.getElementById("admProdId")?.value);
        if (!isEditing) {
          const nameInput = document.getElementById("admProdName");
          const prodName = nameInput ? nameInput.value.trim() : "";
          if (prodName && typeof autoDetectBestProviderForName === "function") {
            const detected = autoDetectBestProviderForName(prodName);
            if (detected) {
              const pSel = document.getElementById("admProdApiProvider");
              if (pSel) pSel.value = detected;
            }
          }
          handleAdmModalProviderChange();
        }
      }
    }
    window.toggleAdmProductSourceFields = toggleAdmProductSourceFields;

    // BỘ LỌC VÀ TÌM NHANH SẢN PHẨM NGUỒN TRONG MODAL SỬA/THÊM SẢN PHẨM
    // BỘ LỌC VÀ TÌM NHANH SẢN PHẨM NGUỒN TRONG MODAL SỬA/THÊM SẢN PHẨM
    function filterAdmModalSourceProducts(keyword) {
      const pSel = document.getElementById("admProdApiProvider");
      const sSel = document.getElementById("admProdApiSourceSelect");
      const countSpan = document.getElementById("admSourceSearchCount");
      const clearBtn = document.getElementById("btnAdmClearSourceSearch");
      if (!sSel) return;

      const rawKw = (keyword || "").trim();
      if (clearBtn) clearBtn.style.display = rawKw ? "inline-block" : "none";

      const provider = pSel ? (pSel.value || "selltainguyenmmo") : "selltainguyenmmo";
      const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);

      let filtered = prods.filter(s => !s.provider || s.provider === provider);
      // Ưu tiên hiển thị: Hàng còn tồn kho (amount > 0) lên trên đầu
      filtered.sort(function(a, b) {
        const stockA = Number(a.amount || 0) > 0 ? 1 : 0;
        const stockB = Number(b.amount || 0) > 0 ? 1 : 0;
        if (stockA !== stockB) return stockB - stockA;
        return (a.name || "").localeCompare(b.name || "");
      });
      const totalInProvider = filtered.length;

      const removeAccents = function(str) {
        return String(str || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/Đ/g, "D").toLowerCase();
      };
      const normalizeSearchText = function(str) {
        let s = removeAccents(str);
        s = s.replace(/\b(intagram|inta|insta|ig)\b/g, "instagram");
        s = s.replace(/\b(titok|tik tok)\b/g, "tiktok");
        s = s.replace(/\bytb\b/g, "youtube");
        s = s.replace(/\b(fb|face)\b/g, "facebook");
        s = s.replace(/\bluoi\b/g, "nuoi");
        s = s.replace(/\bgmai\b/g, "gmail");
        return s;
      };

      const STOP_WORDS = new Set(["da", "va", "cho", "cac", "nhung", "cuc", "ky", "sieu", "loai", "la", "co", "rat", "cap"]);
      let crossProviderMatches = [];

      if (rawKw) {
        const normKw = normalizeSearchText(rawKw);
        const allWords = normKw.split(/\s+/).filter(w => w.length >= 2);
        const meaningfulWords = allWords.filter(w => !STOP_WORDS.has(w));
        const words = meaningfulWords.length > 0 ? meaningfulWords : allWords;

        // 1. Strict match
        let strictMatched = filtered.filter(s => {
          const rawId = String(s.id || "").trim();
          if (rawId === normKw || rawId.includes(normKw)) return true;
          const rawText = normalizeSearchText((s.category || "") + " " + (s.name || "") + " " + rawId);
          return words.length > 0 && words.every(w => rawText.includes(w));
        });

        if (strictMatched.length > 0) {
          filtered = strictMatched;
        } else {
          // 2. Scored fuzzy match
          const scored = [];
          filtered.forEach(s => {
            const rawId = String(s.id || "").trim();
            const rawText = normalizeSearchText((s.category || "") + " " + (s.name || "") + " " + rawId);
            let score = 0;
            words.forEach(w => {
              if (rawText.includes(w)) score += 1;
            });
            if (score > 0) scored.push({ s: s, score: score });
          });
          scored.sort((a, b) => b.score - a.score || (b.s.amount > 0 ? 1 : 0) - (a.s.amount > 0 ? 1 : 0));
          filtered = scored.map(item => item.s);
        }

        if (filtered.length === 0) {
          crossProviderMatches = prods.filter(s => {
            if (s.provider === provider) return false;
            const rawId = String(s.id || "").trim();
            if (rawId === normKw || rawId.includes(normKw)) return true;
            const rawText = normalizeSearchText((s.category || "") + " " + (s.name || "") + " " + rawId);
            return words.length > 0 && words.every(w => rawText.includes(w));
          });
        }
      }

      // Cập nhật nhãn số lượng sản phẩm
      if (countSpan) {
        if (rawKw) {
          if (filtered.length > 0) {
            countSpan.innerHTML = '<span style="color:#10b981; font-weight:700;"><i class="fa-solid fa-check"></i> ' + filtered.length + '/' + totalInProvider + ' SP</span>';
          } else if (crossProviderMatches.length > 0) {
            const topProv = crossProviderMatches[0].provider;
            const topProvCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[topProv]) ? API_SOURCES[topProv] : { name: topProv };
            countSpan.innerHTML = '<span style="color:#38bdf8; cursor:pointer; font-weight:700;" onclick="window.switchAdmModalProvider(\'' + topProv + '\')" title="Bấm để chuyển sang ' + (topProvCfg.name || topProv) + '"><i class="fa-solid fa-arrow-right-arrow-left"></i> Có ' + crossProviderMatches.length + ' SP ở ' + (topProvCfg.name || topProv) + ' (Bấm đổi)</span>';
          } else {
            countSpan.innerHTML = '<span style="color:#f87171;"><i class="fa-solid fa-triangle-exclamation"></i> 0/' + totalInProvider + ' SP</span>';
          }
        } else {
          countSpan.innerHTML = '<span style="color:#94a3b8;">' + totalInProvider + ' SP</span>';
        }
      }

      const pendingVal = sSel.getAttribute("data-pending-id") || "";
      const currentVal = sSel.value || pendingVal;

      // THUẬT TOÁN TỰ ĐỘNG KHỚP SẢN PHẨM MỚI NHẤT (SMART REPLACEMENT):
      const nameInput = document.getElementById("admProdName");
      const currentProdName = (nameInput ? nameInput.value : "").toLowerCase();
      const isGemini18M = currentProdName.includes("gemini") && (currentProdName.includes("18") || currentProdName.includes("veo"));

      let autoSelectedId = "";
      if (currentVal && filtered.some(s => String(s.id) === String(currentVal))) {
        autoSelectedId = String(currentVal);
      } else if (isGemini18M && provider === "selltainguyenmmo") {
        // Tự động bắt gói Gemini 18 tháng live mới nhất (#32428) còn hàng
        const gemini18 = filtered.find(s => {
          const sn = (s.name || "").toLowerCase();
          return sn.includes("18") && (Number(s.amount || 0) > 0 || String(s.id) === "32428");
        }) || filtered.find(s => String(s.id) === "32428");
        if (gemini18) {
          autoSelectedId = String(gemini18.id);
        }
      }

      // Fallback autoSelectedId nếu chưa chọn được
      if (!autoSelectedId && rawKw && filtered.length > 0) {
        const firstInStock = filtered.find(s => Number(s.amount || 0) > 0);
        if (firstInStock && filtered.length <= 5) {
          autoSelectedId = String(firstInStock.id);
        } else if (filtered.length === 1) {
          autoSelectedId = String(filtered[0].id);
        }
      }

      const escFn = (typeof escapeHtml === "function") ? escapeHtml : function(t) { return String(t || '').replace(/[&<>"']/g, ''); };
      let optionsHtml = '';
      if (filtered.length === 0) {
        if (crossProviderMatches.length > 0) {
          optionsHtml = '<option value="">-- Không có ở ' + provider + ' | Có ' + crossProviderMatches.length + ' SP ở nhà cung cấp khác --</option>';
        } else {
          optionsHtml = '<option value="">-- Không tìm thấy SP nào khớp "' + escFn(rawKw) + '" --</option>';
        }
      } else {
        optionsHtml = '<option value="">-- ' + (rawKw ? ('Tìm thấy ' + filtered.length + ' SP (Bấm để chọn)') : ('Chọn sản phẩm nguồn (' + filtered.length + ' SP)')) + ' --</option>';
      }

      // Nếu ID cũ bị web nguồn xoá hoặc hết, giữ lại một lựa chọn để không bị mất liên kết nếu admin chưa muốn đổi
      if (currentVal && !filtered.some(s => String(s.id) === String(currentVal))) {
        const curProdId = document.getElementById("admProdId")?.value;
        const curMap = (typeof getApiProductMapping === "function" && curProdId) ? getApiProductMapping(curProdId) : null;
        const delName = (curMap && curMap.sourceProdName) || "Nguồn Đã Xoá / Hết SP";
        const isOldSel = !autoSelectedId ? ' selected="selected"' : '';
        optionsHtml += '<option value="' + currentVal + '"' + isOldSel + ' data-stock="0">[Đang liên kết cũ: #' + currentVal + ' - ' + delName + '] (Kho: 0 - Đã hết/xoá)</option>';
      }

      optionsHtml += filtered.map(s => {
        const isSel = String(s.id) === String(autoSelectedId) ? ' selected="selected"' : '';
        const pPrice = Number(s.price || 0);
        const pStock = Number(s.amount || 0);
        const priceStr = (typeof formatVND === "function") ? formatVND(pPrice) : (pPrice.toLocaleString("vi-VN") + " đ");
        const stockBadge = pStock > 0 ? (' (Tồn: ' + pStock.toLocaleString() + ')') : ' (HẾT HÀNG - Kho: 0)';
        const recBadge = (String(s.id) === "32428" && isGemini18M) ? ' ⭐ [KHUYÊN DÙNG LIVE: 900+ ACC]' : '';
        return '<option value="' + s.id + '" data-price="' + pPrice + '" data-stock="' + pStock + '"' + isSel + '>' +
          '[' + (s.category || provider) + '] #' + s.id + ' ' + s.name + ' - ' + priceStr + stockBadge + recBadge +
        '</option>';
      }).join("");

      sSel.innerHTML = optionsHtml;
      if (autoSelectedId) {
        sSel.value = String(autoSelectedId);
        sSel.setAttribute("data-pending-id", autoSelectedId);
      }
      if (typeof handleAdmModalSourceChange === "function") {
        handleAdmModalSourceChange();
      }
    }
    window.filterAdmModalSourceProducts = filterAdmModalSourceProducts;

    function switchAdmModalProvider(newProvider) {
      if (!newProvider) return;
      const pSel = document.getElementById("admProdApiProvider");
      if (pSel) {
        pSel.value = newProvider;
        if (typeof updateModalProviderPillsUI === "function") updateModalProviderPillsUI(newProvider);
        const sSel = document.getElementById("admProdApiSourceSelect");
        if (sSel) {
          sSel.setAttribute("data-active-provider", newProvider);
        }
        const searchInput = document.getElementById("admProdApiSourceSearch");
        filterAdmModalSourceProducts(searchInput ? searchInput.value : "");
        const cfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[newProvider]) ? API_SOURCES[newProvider] : { name: newProvider };
        if (typeof showToast === "function") showToast("Đã chuyển sang nguồn " + (cfg.name || newProvider), "info");

        const curProds = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
          ? window.cachedSourceProducts
          : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
        const inProv = curProds.filter(p => p.provider === newProvider);
        if (inProv.length <= 1 && typeof fetchSingleSourceProducts === "function") {
          fetchSingleSourceProducts(newProvider, false);
        }
      }
    }
    window.switchAdmModalProvider = switchAdmModalProvider;

    let _admModalSourceFilterTimer = null;
    function debouncedAdmModalSourceFilter(val, delay = 120) {
      if (_admModalSourceFilterTimer) clearTimeout(_admModalSourceFilterTimer);
      _admModalSourceFilterTimer = setTimeout(function() {
        filterAdmModalSourceProducts(val);
      }, delay);
    }
    window.debouncedAdmModalSourceFilter = debouncedAdmModalSourceFilter;

    function resetAdmModalApiSearchUI() {
      const searchInput = document.getElementById("admProdApiSourceSearch");
      if (searchInput) searchInput.value = "";
      const clearBtn = document.getElementById("btnAdmClearSourceSearch");
      if (clearBtn) clearBtn.style.display = "none";
      const sugBox = document.getElementById("admModalProviderSuggestions");
      if (sugBox) {
        sugBox.style.display = "none";
        sugBox.innerHTML = "";
      }
      const countSpan = document.getElementById("admSourceSearchCount") || document.getElementById("admProdApiSourceCount");
      if (countSpan) countSpan.innerHTML = "";
      if (typeof filterAdmModalSourceProducts === "function") {
        filterAdmModalSourceProducts("");
      }
    }
    window.resetAdmModalApiSearchUI = resetAdmModalApiSearchUI;

    function clearAdmModalSourceSearch() {
      resetAdmModalApiSearchUI();
      const searchInput = document.getElementById("admProdApiSourceSearch");
      if (searchInput) searchInput.focus();
    }
    window.clearAdmModalSourceSearch = clearAdmModalSourceSearch;

    function extractSmartProductKeyword(name, cat) {
      if (!name && !cat) return "";
      const raw = String(name || "").trim();
      const full = (raw + " " + (cat || "")).toLowerCase();

      // 1. Nhận diện nền tảng / thương hiệu cụ thể (Ưu tiên thương hiệu độc lập trước)
      if (/\bcanva\b/i.test(full)) return "Canva";
      if (/\bcapcut\b/i.test(full)) return "Capcut";
      if (/\b(gemini|veo\s*3|veo3)\b/i.test(full)) return "Gemini";
      if (/\b(chatgpt|gpt|openai|codex|claude)\b/i.test(full)) return "ChatGPT";
      if (/\bkling\b/i.test(full)) return "Kling";
      if (/\bnetflix\b/i.test(full)) return "Netflix";
      if (/\bspotify\b/i.test(full)) return "Spotify";
      if (/\b(youtube|ytb)\b/i.test(full)) return "Youtube";
      if (/\bdiscord\b/i.test(full)) return "Discord";
      if (/\b(telegram|tele)\b/i.test(full)) return "Telegram";
      if (/\b(twitter|x\.com)\b/i.test(full)) return "Twitter";
      if (/\bthreads\b/i.test(full)) return "Threads";
      if (/\b(instagram|intagram|insta|ig)\b/i.test(full)) return "Instagram";
      if (/\b(tiktok|tik\s*tok)\b/i.test(full)) return "TikTok";
      if (/\b(facebook|fb|via|bm|clone|fanpage|page)\b/i.test(full)) return "Facebook";
      if (/\b(surfshark)\b/i.test(full)) return "Surfshark";
      if (/\b(nordvpn|nord)\b/i.test(full)) return "NordVPN";
      if (/\b(expressvpn|express\s*vpn)\b/i.test(full)) return "ExpressVPN";
      if (/\bhma\b/i.test(full)) return "HMA";
      if (/\b(proxy|ipv4|ipv6|socks|4g|datacenter)\b/i.test(full)) return "Proxy";
      if (/\b(hotmail|outlook)\b/i.test(full)) return "Hotmail";
      if (/\b(gmail|mail\s*domain|mail\s*edu|google\s*workspace)\b/i.test(full)) return "Gmail";

      // 2. Bóc tách làm sạch tên nếu không rơi vào platform trên
      let clean = raw.replace(/^(tài\s*khoản|tai\s*khoan|acc|tk|nâng\s*cấp|nang\s*cap|chuyên\s*cung\s*cấp|cho\s*thuê|thue|thuê)\s+/i, "").trim();
      clean = clean.replace(/\b(\d+\s*(ngày|ngay|tháng|thang|năm|nam|h|giờ|gio|phút|phut)|chính\s*chủ|chinh\s*chu|riêng\s*tư|rieng\s*tu|khỏe|khoe|ngâm|ngam|lâu|lau|cổ|co|new|trâu|trau|zin|random|siêu|sieu|chất\s*lượng|uy\s*tín|giá\s*rẻ|bảo\s*hành|bao\s*die|live|đã|da)\b/gi, "").trim();
      const parts = clean.split(/\s+/).filter(w => w.length >= 2).slice(0, 2).join(" ");
      return parts || clean || raw.split(/\s+/)[0] || "";
    }
    window.extractSmartProductKeyword = extractSmartProductKeyword;

    function autoFillSourceSearchFromName() {
      const nameInput = document.getElementById("admProdName");
      const searchInput = document.getElementById("admProdApiSourceSearch");
      const catSelect = document.getElementById("admProdCategory");
      if (!nameInput || !searchInput) return;
      let val = nameInput.value.trim();
      let cat = catSelect ? catSelect.value.trim() : "";
      if (!val && !cat) {
        if (typeof showToast === "function") showToast("Vui lòng nhập Tên Sản Phẩm ở trên trước!", "warning");
        nameInput.focus();
        return;
      }

      const finalKw = extractSmartProductKeyword(val, cat);
      searchInput.value = finalKw;
      const clearBtn = document.getElementById("btnAdmClearSourceSearch");
      if (clearBtn) clearBtn.style.display = finalKw ? "inline-block" : "none";
      searchInput.focus();

      // Kiểm tra xem nhà cung cấp hiện tại có SP nào khớp finalKw không
      const pSel = document.getElementById("admProdApiProvider");
      const curProv = pSel ? pSel.value : "nguyenlieummo";
      const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
      
      const curMatches = prods.filter(s => (!s.provider || s.provider === curProv) && ((s.name||"") + " " + (s.category||"")).toLowerCase().includes(finalKw.toLowerCase()));
      if (curMatches.length === 0) {
        // Tìm nhà cung cấp có nhiều SP khớp từ khóa nhất
        const provCounts = {};
        prods.forEach(s => {
          if (!s || !s.provider) return;
          if (((s.name||"") + " " + (s.category||"")).toLowerCase().includes(finalKw.toLowerCase())) {
            provCounts[s.provider] = (provCounts[s.provider] || 0) + (s.amount > 0 ? 2 : 1);
          }
        });
        const bestProv = Object.keys(provCounts).sort((a,b) => provCounts[b] - provCounts[a])[0];
        if (bestProv && bestProv !== curProv) {
          selectModalApiProvider(bestProv);
          if (typeof showToast === "function") {
            const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[bestProv]) ? API_SOURCES[bestProv] : null;
            showToast("🪄 Đã tự động chuyển sang [" + (pCfg ? pCfg.name : bestProv) + "] vì có SP khớp \"" + finalKw + "\"!", "success");
          }
          return;
        }
      }

      filterAdmModalSourceProducts(finalKw);
      if (typeof renderModalProviderSuggestions === "function") {
        renderModalProviderSuggestions(finalKw, curProv);
      }
      if (typeof showToast === "function") showToast("🪄 Đã tìm nhanh SP nguồn theo: \"" + finalKw + "\"", "info");
    }
    window.autoFillSourceSearchFromName = autoFillSourceSearchFromName;
    window.quickFillApiSearchFromName = autoFillSourceSearchFromName;

    
    // QUÉT TRỰC TIẾP TOÀN BỘ SẢN PHẨM TỪ 1 NHÀ CUNG CẤP CỤ THỂ (SELLTAINGUYENMMO, ULTRAMMO, NGUYENLIEUMMO)
    async function fetchSingleSourceProducts(provider, isManual = false) {
      provider = provider || "selltainguyenmmo";
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : null;
      if (!pCfg) return [];

      let apiKey = pCfg.apiKey || (typeof localStorage !== "undefined" ? localStorage.getItem("mmo_source_key_" + provider) : "") || "";

      const countSpan = document.getElementById("admSourceSearchCount") || document.getElementById("admProdApiSourceCount");
      if (countSpan) {
        countSpan.innerHTML = '<span style="color:#38bdf8;"><i class="fa-solid fa-spinner fa-spin"></i> Đang quét SP ' + (pCfg.name || provider) + '...</span>';
      }

      try {
        let payload = { provider: provider, baseUrl: pCfg.baseUrl };
        if (pCfg.authType === "userpass") {
          payload.username = pCfg.username;
          payload.password = pCfg.password;
        } else {
          payload.apiKey = pCfg.apiKey;
        }

        const res = await executeSourceApiCall("getProducts", payload);
        let freshProds = [];

        if (res && res.success && Array.isArray(res.categories)) {
          res.categories.forEach(function(cat) {
            (cat.products || cat.accounts || []).forEach(function(p) {
              freshProds.push({
                id: String(p.id),
                name: p.name,
                price: Number(p.price) || 0,
                amount: Number(p.amount || p.accounts) || 0,
                category: cat.name,
                provider: provider
              });
            });
          });
        }

        if (freshProds.length > 0) {
          let curCached = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
            ? window.cachedSourceProducts
            : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);

          const otherProds = curCached.filter(p => p.provider !== provider);
          const merged = otherProds.concat(freshProds);

          window.cachedSourceProducts = merged;
          cachedSourceProducts = merged;
          if (typeof rebuildSourceProductsFastIndex === "function") {
            rebuildSourceProductsFastIndex(merged);
          }

          try {
            localStorage.setItem("mmo_cached_source_products", JSON.stringify(merged));
          } catch(quotaErr) {
            try { sessionStorage.setItem("mmo_cached_source_products", JSON.stringify(merged)); } catch(e) {}
          }

          if (isManual && typeof showToast === "function") {
            showToast("Đã quét thành công " + freshProds.length + " sản phẩm từ " + pCfg.name + "!", "success");
          }
          return freshProds;
        } else {
          if (isManual && typeof showToast === "function") {
            showToast("Không lấy được sản phẩm từ " + pCfg.name + ". Đang dùng dữ liệu sẵn có.", "warning");
          }
        }
      } catch(err) {
        console.warn("fetchSingleSourceProducts error for " + provider + ":", err);
        if (isManual && typeof showToast === "function") {
          showToast("Lỗi kết nối tới " + (pCfg ? pCfg.name : provider) + ": " + err.message, "error");
        }
      } finally {
        const modal = document.getElementById("adminProductModal");
        if (modal && modal.style.display !== "none" && typeof filterAdmModalSourceProducts === "function") {
          const searchInput = document.getElementById("admProdApiSourceSearch");
          filterAdmModalSourceProducts(searchInput ? searchInput.value : "");
        }
      }
      return [];
    }
    window.fetchSingleSourceProducts = fetchSingleSourceProducts;

    async function rescanCurrentModalProvider() {
      const pSel = document.getElementById("admProdApiProvider");
      const prov = pSel ? (pSel.value || "selltainguyenmmo") : "selltainguyenmmo";
      const cfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[prov]) ? API_SOURCES[prov] : { name: prov };
      const provName = cfg.name || (prov + ".com");

      let btn = document.getElementById("btnAdmRescanCurrentModalProvider");
      if (!btn) {
        const allBtns = document.querySelectorAll("button");
        for (let b = 0; b < allBtns.length; b++) {
          if (allBtns[b].getAttribute("onclick") && allBtns[b].getAttribute("onclick").includes("rescanCurrentModalProvider")) {
            btn = allBtns[b];
            break;
          }
        }
      }

      const origBtnHtml = btn ? btn.innerHTML : "";
      if (btn) {
        btn.innerHTML = '<i class="fa-solid fa-rotate fa-spin"></i> Đang quét...';
        btn.disabled = true;
      }

      if (typeof showToast === "function") showToast("⏳ Đang quét toàn bộ danh mục live từ " + provName + "...", "info");
      const countSpan = document.getElementById("admSourceSearchCount") || document.getElementById("admProdApiSourceCount");
      if (countSpan) {
        countSpan.innerHTML = '<span style="color:#38bdf8; font-weight:600;"><i class="fa-solid fa-spinner fa-spin"></i> Đang tải live từ ' + provName + '...</span>';
      }

      try {
        if (!window._provFetchedAt) window._provFetchedAt = {};
        window._provFetchedAt[prov] = 0;
        const prods = await fetchSingleSourceProducts(prov, true);
        if (prods && prods.length > 0) {
          if (typeof showToast === "function") {
            showToast("✅ Đã cập nhật xong " + prods.length.toLocaleString() + " sản phẩm từ " + provName + "!", "success");
          }
        }
      } catch(err) {
        console.warn("rescanCurrentModalProvider error:", err);
        if (typeof showToast === "function") showToast("❌ Lỗi quét nguồn " + provName + ": " + (err.message || err), "error");
        if (countSpan) {
          countSpan.innerHTML = '<span style="color:#f87171;"><i class="fa-solid fa-triangle-exclamation"></i> Lỗi: ' + (err.message || err) + '</span>';
        }
      } finally {
        if (btn) {
          btn.innerHTML = origBtnHtml || '<i class="fa-solid fa-rotate"></i> Quét lại SP';
          btn.disabled = false;
        }
      }
    }
    window.rescanCurrentModalProvider = rescanCurrentModalProvider;

    function renderModalProviderSuggestions(keyword, currentProvider) {
      const box = document.getElementById("admModalProviderSuggestions");
      if (!box) return;
      const rawKw = (keyword || "").trim().toLowerCase();
      if (!rawKw) {
        box.style.display = "none";
        box.innerHTML = "";
        return;
      }

      const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);

      const otherMatches = {};
      prods.forEach(p => {
        if (!p || !p.provider || p.provider === currentProvider) return;
        const txt = ((p.name || "") + " " + (p.category || "")).toLowerCase();
        if (txt.includes(rawKw)) {
          if (!otherMatches[p.provider]) otherMatches[p.provider] = 0;
          otherMatches[p.provider]++;
        }
      });

      const matchedProvs = Object.keys(otherMatches).filter(k => otherMatches[k] > 0);
      if (matchedProvs.length === 0) {
        box.style.display = "none";
        box.innerHTML = "";
        return;
      }

      let html = '<div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:6px;">' +
        '<span style="color:#fbbf24;"><i class="fa-solid fa-lightbulb"></i> Tìm thấy SP khớp "<strong>' + (typeof escapeHtml === "function" ? escapeHtml(keyword) : keyword) + '</strong>" tại nguồn khác:</span>' +
        '<div style="display:flex; gap:6px; flex-wrap:wrap;">';

      matchedProvs.forEach(prov => {
        const count = otherMatches[prov];
        const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[prov]) ? API_SOURCES[prov] : null;
        const provName = pCfg ? pCfg.name : prov;
        html += '<button type="button" onclick="selectModalApiProvider(\'' + prov + '\')" ' +
          'style="padding:3px 8px; border-radius:4px; font-size:0.72rem; font-weight:700; cursor:pointer; background:rgba(56,189,248,0.18); border:1px solid #38bdf8; color:#38bdf8; display:inline-flex; align-items:center; gap:4px;">' +
          '<i class="fa-solid fa-arrow-right-arrow-left"></i> Chuyển sang ' + (typeof escapeHtml === "function" ? escapeHtml(provName) : provName) + ' (' + count + ' SP)' +
        '</button>';
      });

      html += '</div></div>';
      box.innerHTML = html;
      box.style.display = "block";
    }
    window.renderModalProviderSuggestions = renderModalProviderSuggestions;

    function handleAdmModalProviderChange() {
      const pSel = document.getElementById("admProdApiProvider");
      const prov = pSel ? (pSel.value || "nguyenlieummo") : "nguyenlieummo";
      if (typeof updateModalProviderPillsUI === "function") {
        updateModalProviderPillsUI(prov);
      }
      const sSel = document.getElementById("admProdApiSourceSelect");
      if (sSel) {
        sSel.value = "";
        sSel.removeAttribute("data-pending-id");
        sSel.setAttribute("data-active-provider", prov);
      }
      const info = document.getElementById("admProdApiSourceInfo");
      if (info) info.innerHTML = '<span style="color:#94a3b8;"><i class="fa-solid fa-spinner fa-spin"></i> Đang tải SP từ ' + prov + '...</span>';

      // Tự động nhận diện từ khóa sản phẩm từ tên đang sửa để lọc ngay trong nguồn mới
      const nameInput = document.getElementById("admProdName");
      const catSelect = document.getElementById("admProdCategory");
      const prodName = nameInput ? nameInput.value.trim() : "";
      const prodCat = catSelect ? catSelect.value.trim() : "";
      const autoKw = (prodName || prodCat) ? (typeof extractSmartProductKeyword === "function" ? extractSmartProductKeyword(prodName, prodCat) : prodName.split(/\s+/).slice(0, 2).join(" ")) : "";

      const searchInput = document.getElementById("admProdApiSourceSearch");
      if (searchInput) searchInput.value = autoKw;
      const clearBtn = document.getElementById("btnAdmClearSourceSearch");
      if (clearBtn) clearBtn.style.display = autoKw ? "inline-block" : "none";

      filterAdmModalSourceProducts(autoKw);

      // Hiển thị gợi ý nguồn khác nếu từ khóa có trên nguồn khác
      if (typeof renderModalProviderSuggestions === "function") {
        renderModalProviderSuggestions(autoKw, prov);
      }

      if (typeof fetchSingleSourceProducts === "function") {
        if (!window._provFetchedAt) window._provFetchedAt = {};
        const lastFetch = window._provFetchedAt[prov] || 0;
        const curProdsInProv = ((window.cachedSourceProducts || cachedSourceProducts || []).filter(p => p.provider === prov));
        if (curProdsInProv.length <= 1 || Date.now() - lastFetch > 60000) {
          window._provFetchedAt[prov] = Date.now();
          fetchSingleSourceProducts(prov, false);
        }
      }
    }
    window.handleAdmModalProviderChange = handleAdmModalProviderChange;
    

    function handleAdmModalSourceChange() {
      const sSel = document.getElementById("admProdApiSourceSelect");
      const pSel = document.getElementById("admProdApiProvider");
      const info = document.getElementById("admProdApiSourceInfo");
      if (!sSel || !info) return;
      if (sSel.value) {
        sSel.setAttribute("data-pending-id", sSel.value);
        if (pSel && pSel.value) sSel.setAttribute("data-active-provider", pSel.value);
      }
      const opt = (sSel.selectedOptions && sSel.selectedOptions[0]) ? sSel.selectedOptions[0] : (sSel.options ? sSel.options[sSel.selectedIndex] : null);
      if (opt && opt.value) {
        const price = (typeof opt.getAttribute === "function" ? opt.getAttribute("data-price") : 0) || 0;
        const stock = (typeof opt.getAttribute === "function" ? opt.getAttribute("data-stock") : 0) || 0;
        info.innerHTML = '<i class="fa-solid fa-circle-info"></i> Giá nhập gốc: <strong>' + formatVND(price) + '</strong> | Tồn kho live nguồn: <strong style="color:#10b981;">' + Number(stock).toLocaleString() + ' acc</strong>';
      } else {
        info.innerHTML = '<span style="color:#94a3b8;">Vui lòng chọn sản phẩm tương ứng từ nguồn API để khách mua sẽ được tự động cấp tài khoản.</span>';
      }
    }
    window.handleAdmModalSourceChange = handleAdmModalSourceChange;
  

    function openCurrentDetailProductEditModal(forceApi) {
      let p = (window.currentSelectedProduct && window.currentSelectedProduct.id && window.currentSelectedProduct.id !== "PROD_CODE")
        ? window.currentSelectedProduct
        : (window._currentActiveDetailProduct && window._currentActiveDetailProduct.id && window._currentActiveDetailProduct.id !== "PROD_CODE"
          ? window._currentActiveDetailProduct
          : null);
      let pId = (p && p.id) ? p.id : "";
      if (!pId) {
        const sp = new URLSearchParams(window.location.search);
        const urlProd = sp.get("prod") || sp.get("product") || sp.get("id") || "";
        if (urlProd && urlProd !== "PROD_CODE") pId = urlProd.trim();
      }
      if (!pId) {
        const dtlIdEl = document.getElementById("dtlId");
        const val = dtlIdEl ? dtlIdEl.innerText.trim() : "";
        if (val && val !== "PROD_CODE") pId = val;
      }
      if (!pId) {
        const dtlTitleEl = document.getElementById("dtlTitle");
        const tVal = dtlTitleEl ? dtlTitleEl.innerText.trim().toLowerCase() : "";
        if (tVal && typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) {
          const match = MOCK_DATA.products.find(x => x && x.name && x.name.toLowerCase().trim() === tVal);
          if (match && match.id && match.id !== "PROD_CODE") {
            pId = match.id;
            p = match;
          }
        }
      }
      if (!pId || pId === "PROD_CODE") {
        if (typeof showToast === "function") showToast("Vui lòng chọn sản phẩm cần sửa!", "warning");
        return;
      }
      if (!p && typeof findShopProduct === "function") p = findShopProduct(pId);
      if (!p && typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) {
        p = MOCK_DATA.products.find(x => x && (x.id === pId || (x.slug && x.slug === pId)));
      }
      const isApi = (forceApi === true) || (p && ((p.deliveryType === "api" || p.delivery_type === "api") || !!(p.apiMapping && p.apiMapping.enabled && p.apiMapping.sourceProdId)));
      openEditProductModal(pId, isApi);
    }
    window.openCurrentDetailProductEditModal = openCurrentDetailProductEditModal;
