    function getActiveProductForSharing() {
      let p = (typeof currentSelectedProduct !== "undefined" && currentSelectedProduct)
        || window._currentActiveDetailProduct
        || window.currentSelectedProduct
        || null;
      if (!p) {
        try {
          const sp = new URLSearchParams(window.location.search);
          const pid = sp.get('prod') || sp.get('product') || sp.get('q');
          if (pid && typeof findShopProduct === "function") p = findShopProduct(pid);
        } catch(e) {}
      }
      if (!p) {
        try {
          const dtlIdEl = document.getElementById("dtlId");
          if (dtlIdEl && dtlIdEl.innerText && typeof findShopProduct === "function") {
            p = findShopProduct(dtlIdEl.innerText.trim());
          }
        } catch(e) {}
      }
      return p;
    }

    function copyProductAffiliateLink(withCaption) {
      const p = getActiveProductForSharing();
      const dtlIdEl = document.getElementById("dtlId");
      const dtlIdText = (dtlIdEl && dtlIdEl.innerText && dtlIdEl.innerText.trim()) ? dtlIdEl.innerText.trim() : "";
      const sp = new URLSearchParams(window.location.search);
      const prodId = (p && p.id) || dtlIdText || sp.get('prod') || sp.get('product') || sp.get('q');
      if (!prodId) {
        if (typeof showToast === "function") showToast("Không tìm thấy thông tin sản phẩm để lấy link!", "warning");
        return;
      }
      let isAff = false;
      let refCode = "";
      if (typeof currentUser !== "undefined" && currentUser) {
        refCode = (currentUser.email ? currentUser.email.split('@')[0] : (currentUser.userId || "aff")).toLowerCase();
        isAff = true;
      }
      // [SMART SOCIAL SHARE LINK]: Dùng endpoint OG Proxy để Facebook, Zalo, Telegram, Twitter luôn hiện ảnh và tên sản phẩm 100%
      let shareUrl = "https://mmo-shop-api.khotaikhoanso-net.workers.dev/og?prod=" + encodeURIComponent(prodId);
      if (refCode) {
        shareUrl += "&ref=" + encodeURIComponent(refCode);
      }
      const curOrigin = window.location.origin;
      if (curOrigin && !curOrigin.includes("cuahangcuaban.com") && curOrigin.startsWith("http")) {
        shareUrl += "&domain=" + encodeURIComponent(curOrigin);
      }
      
      const pName = (p && p.name) ? p.name : "Sản phẩm MMO";
      const pPrice = (typeof formatVND === "function") ? formatVND(window.currentSelectedPrice || (p && p.price) || 0) : ((window.currentSelectedPrice || (p && p.price) || 0) + " đ");
      let commRate = 10;
      if (p) {
        if (typeof p.commissionRate === "number" && !isNaN(p.commissionRate)) commRate = p.commissionRate;
        else if (typeof p.commission === "number" && !isNaN(p.commission)) commRate = p.commission;
        else {
          const m = String(p.commission || p.commissionRate || "").match(/[0-9]+/);
          commRate = m ? parseInt(m[0], 10) : 10;
        }
      }
      if (isNaN(commRate) || commRate <= 0) commRate = 10;

      if (withCaption) {
        const caption = "🔥 " + pName + "\n" +
          "💰 Giá chỉ: " + pPrice + "\n" +
          "🛡️ Bảo hành: " + ((p && p.warranty) ? p.warranty : "Bảo hành 1 đổi 1") + " - Giao tự động 24/7\n" +
          "👉 Mua ngay tại: " + shareUrl;
        copyTextDirect(caption, false);
        if (typeof showToast === "function") {
          showToast("🎉 Đã sao chép nội dung bài đăng kèm link giới thiệu!", "success");
        }
      } else {
        copyTextDirect(shareUrl, false);
        if (typeof showToast === "function") {
          if (isAff) {
            showToast("🎉 Đã sao chép link sản phẩm (kèm mã hoa hồng " + commRate + "% của bạn):\n" + shareUrl, "success");
          } else {
            showToast("✅ Đã sao chép link sản phẩm: " + shareUrl + "\n💡 Đăng nhập tài khoản để nhận hoa hồng " + commRate + "% khi chia sẻ!", "info");
          }
        }
      }
    }
    window.copyProductAffiliateLink = copyProductAffiliateLink;

    function shareProductToSocial(platform) {
      const p = getActiveProductForSharing();
      const dtlIdEl = document.getElementById("dtlId");
      const dtlIdText = (dtlIdEl && dtlIdEl.innerText && dtlIdEl.innerText.trim()) ? dtlIdEl.innerText.trim() : "";
      const sp = new URLSearchParams(window.location.search);
      const prodId = (p && p.id) || dtlIdText || sp.get('prod') || sp.get('product') || sp.get('q') || "";
      let refCode = "";
      if (typeof currentUser !== "undefined" && currentUser && prodId) {
        refCode = (currentUser.email ? currentUser.email.split('@')[0] : (currentUser.userId || "aff")).toLowerCase();
      }
      let shareUrl = "https://cuahangcuaban.com/";
      if (prodId) {
        shareUrl = "https://mmo-shop-api.khotaikhoanso-net.workers.dev/og?prod=" + encodeURIComponent(prodId);
        if (refCode) shareUrl += "&ref=" + encodeURIComponent(refCode);
        const curOrigin = window.location.origin;
        if (curOrigin && !curOrigin.includes("cuahangcuaban.com") && curOrigin.startsWith("http")) {
          shareUrl += "&domain=" + encodeURIComponent(curOrigin);
        }
      }
      const priceStr = (typeof formatVND === "function") ? formatVND(window.currentSelectedPrice || (p && p.price) || 0) : "";
      const title = (p && p.name) ? (p.name + (priceStr ? (" - " + priceStr) : "") + " | khotaikhoanso.net") : "khotaikhoanso.net - Mua Bán Tài Khoản MMO";

      if (platform === "facebook") {
        window.open("https://www.facebook.com/sharer/sharer.php?u=" + encodeURIComponent(shareUrl), "_blank", "width=600,height=500,menubar=no,toolbar=no");
      } else if (platform === "zalo") {
        window.open("https://zalo.me/share?url=" + encodeURIComponent(shareUrl) + "&title=" + encodeURIComponent(title), "_blank", "width=600,height=500,menubar=no,toolbar=no");
      } else if (platform === "telegram") {
        window.open("https://t.me/share/url?url=" + encodeURIComponent(shareUrl) + "&text=" + encodeURIComponent(title + "\n" + shareUrl), "_blank", "width=600,height=500,menubar=no,toolbar=no");
      } else if (platform === "twitter") {
        window.open("https://twitter.com/intent/tweet?url=" + encodeURIComponent(shareUrl) + "&text=" + encodeURIComponent(title), "_blank", "width=600,height=500,menubar=no,toolbar=no");
      }
    }
