      const amt = actionType === "sub" ? -rawAmt : rawAmt;
      
      const noteInp = document.getElementById("balModalNoteInput") || document.getElementById("adjBalReason");
      const reason = noteInp?.value?.trim() || (amt >= 0 ? "Nạp tiền thủ công qua ngân hàng" : "Trừ tiền thủ công bởi Quản trị viên");

