      if (pId && typeof KTS_KNOWN_CDN_MAP !== "undefined") {
        if (KTS_KNOWN_CDN_MAP[pId]) return KTS_KNOWN_CDN_MAP[pId];
        if (KTS_KNOWN_CDN_MAP[pId.toUpperCase()]) return KTS_KNOWN_CDN_MAP[pId.toUpperCase()];
      }

