      return (KTS_IMG && KTS_IMG["gemini_pro_veo3.png"] && (pName.includes("gemini") || pName.includes("veo"))) ? KTS_IMG["gemini_pro_veo3.png"] : "https://iili.io/nGs8RDv.jpg";
