      const accs = map[targetKey];
      if (!accs || !Array.isArray(accs) || accs.length === 0) {
        return [];
      }

      const taken = accs.splice(0, qtyToTake);
      map[targetKey] = accs;
      if (variantIndex === 0 || variantIndex === "0") { map[pId] = accs; }
      saveProductStocksMap(map);

      // Cập nhật lại tổng tồn kho cho sản phẩm
      const totalStock = (typeof getVariantStockCount === "function") ? getVariantStockCount(product, null) : accs.length;
      if (product) product.stock = totalStock;

      if (typeof saveProductsToStorage === "function") saveProductsToStorage();
      
      syncAllOpenViewsStock(product.id, totalStock, accs);
      return taken;
