    var _cachedApiProductMappings = null;
    function invalidateApiProductMappingsCache() {
      _cachedApiProductMappings = null;
      if (typeof _cachedApiSourceAlerts !== "undefined") {
        _cachedApiSourceAlerts = null;
      }
    }
    window.invalidateApiProductMappingsCache = invalidateApiProductMappingsCache;

    function getApiProductMappings() {
      if (_cachedApiProductMappings) {
        return _cachedApiProductMappings;
      }
      let result = Object.assign({}, DEFAULT_API_PRODUCT_MAPPINGS);
      try {
        const stored = localStorage.getItem("mmo_api_product_mappings");
        if (stored) {
          const parsed = JSON.parse(stored);
          if (parsed && typeof parsed === "object") {
            Object.keys(parsed).forEach(k => {
              if (parsed[k] && typeof parsed[k] === "object") {
                result[k] = Object.assign({}, result[k] || {}, parsed[k]);
              }
            });
          }
        }
      } catch(e) {}

      // Đồng bộ trạng thái đã gỡ/xoá SP qua O(1) index siêu tốc
      Object.keys(result).forEach(k => {
        const item = result[k];
        if (!item) return;

        if (item.sourceProdId) {
          const cleanSrcId = String(item.sourceProdId || "").trim().replace(/^#/, "");
          let inSrc = (typeof getFastSourceProduct === "function") ? getFastSourceProduct(item.provider, cleanSrcId) : null;
          if (!inSrc && typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) {
            inSrc = cachedSourceProducts.find(s => String(s.id).trim().replace(/^#/, "") === cleanSrcId && (!item.provider || s.provider === item.provider))
                 || cachedSourceProducts.find(s => String(s.id).trim().replace(/^#/, "") === cleanSrcId);
          }
          const provLoaded = (typeof isFastSourceProviderLoaded === "function") ? isFastSourceProviderLoaded(item.provider) : false;
          if (inSrc && typeof inSrc.amount === "number") {
            item.sourceStock = inSrc.amount;
            item.isSourceDeleted = false;
            if (inSrc.price) item.sourcePrice = inSrc.price;
            if (inSrc.name) item.sourceProdName = inSrc.name;
          } else if (provLoaded) {
            item.isSourceDeleted = true;
            item.sourceStock = 0;
          }
        }
        if (item.isSourceDeleted) {
          item.sourceStock = 0;
        }
      });
      _cachedApiProductMappings = result;
      return result;
    }
    window.getApiProductMappings = getApiProductMappings;

    var _debouncedSaveApiMappingsTimer = null;
    function saveApiProductMappings(maps) {
      try {
        if (typeof invalidateApiProductMappingsCache === "function") {
          invalidateApiProductMappingsCache();
        }
        localStorage.setItem("mmo_api_product_mappings", JSON.stringify(maps || {}));
        
        // DEBOUNCE 15 GIÂY: Tránh spam request POST lên Google Apps Script làm nghẽn toàn sàn
        if (_debouncedSaveApiMappingsTimer) clearTimeout(_debouncedSaveApiMappingsTimer);
        _debouncedSaveApiMappingsTimer = setTimeout(function() {
          if (typeof callGasApi === "function") {
            callGasApi("adminSaveSettings", {
              settings: {
                API_PRODUCT_MAPPINGS: JSON.stringify(maps || {})
              }
            }).catch(function() {});
          }
        }, 15000);
      } catch(e) {}
    }
    window.saveApiProductMappings = saveApiProductMappings;

    function normApiText(str) {
      return String(str || '').toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[đĐ]/g, 'd')
        .replace(/[^a-z0-9]/g, ' ')
        .replace(/\s+/g, ' ').trim();
    }
    window.normApiText = normApiText;

    function isProductApi(productOrId) {
      if (!productOrId) return false;
      const prod = (typeof productOrId === "object") ? productOrId : (typeof findShopProduct === "function" ? findShopProduct(productOrId) : null);
      if (prod && (prod.deliveryType === "local" || prod.delivery_type === "local" || prod.deliveryType === "manual" || prod.delivery_type === "manual")) return false;
      if (prod && (prod.deliveryType === "api" || prod.delivery_type === "api")) return true;
      if (prod && prod.apiMapping && prod.apiMapping.enabled && prod.apiMapping.sourceProdId) return true;
      const pId = typeof productOrId === "string" ? productOrId : (prod ? prod.id : "");
      if (typeof getApiProductMapping === "function") {
        const map = getApiProductMapping(pId || prod);
        if (map && map.enabled && map.sourceProdId) return true;
      }
      return false;
    }
    window.isProductApi = isProductApi;

    function getApiProductMapping(productOrId) {
      if (!productOrId) return null;
      const prodId = typeof productOrId === "string" ? productOrId.trim() : (productOrId.id || "").trim();
      const isIdKey = /^(PROD_|SP_)/i.test(prodId);
      const prodObj = typeof productOrId === "object" ? productOrId : ((typeof findShopProduct === "function") ? findShopProduct(prodId) : null);
      const prodName = prodObj ? (prodObj.name || "") : (typeof productOrId === "string" ? productOrId.trim() : "");

      const maps = getApiProductMappings();

      function enrichMapping(m) {
        if (!m || !m.enabled || !m.sourceProdId) return null;
        const res = Object.assign({}, m);
        const cleanSrcId = String(res.sourceProdId || "").trim().replace(/^#/, "");
        let stock = (res.sourceStock !== undefined && res.sourceStock !== null) ? Number(res.sourceStock) : 0;
        let inSrc = (typeof getFastSourceProduct === "function") ? getFastSourceProduct(res.provider, cleanSrcId) : null;
        if (!inSrc && typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) {
          inSrc = cachedSourceProducts.find(s => String(s.id).trim().replace(/^#/, "") === cleanSrcId && (!res.provider || s.provider === res.provider))
               || cachedSourceProducts.find(s => String(s.id).trim().replace(/^#/, "") === cleanSrcId);
        }
        if (inSrc && typeof inSrc.amount === "number") {
          stock = inSrc.amount;
          res.sourceStock = stock;
          res.isSourceDeleted = false;
          if (inSrc.price) res.sourcePrice = inSrc.price;
          if (inSrc.name) res.sourceProdName = inSrc.name;
        } else {
          const provLoaded = (typeof isFastSourceProviderLoaded === "function") ? isFastSourceProviderLoaded(res.provider) : false;
          if (provLoaded) {
            stock = 0;
            res.sourceStock = 0;
            res.isSourceDeleted = true;
          } else {
            if (res.isSourceDeleted) {
              stock = 0;
              res.sourceStock = 0;
            }
          }
        }
        res.sourceStock = Math.max(0, stock);
        return res;
      }

      // [BẢO VỆ KHO NỘI BỘ]: Nếu sản phẩm là kho nội bộ và không có mapping API nào, không tự động gán
      const isExplicitLocal = prodObj && (prodObj.deliveryType === "local" || prodObj.delivery_type === "local" || prodObj.deliveryType === "manual" || prodObj.delivery_type === "manual") && !maps[prodId] && !DEFAULT_API_PRODUCT_MAPPINGS[prodId] && !(prodObj.apiMapping && prodObj.apiMapping.enabled);
      if (isExplicitLocal) {
        if (prodObj.apiMapping && prodObj.apiMapping.enabled && prodObj.apiMapping.sourceProdId) {
          return enrichMapping(prodObj.apiMapping);
        }
        return null;
      }

      // [BUILT-IN DEFAULT MAPPINGS FOR ON-DEMAND PRODUCTS]
      // Tự động chuyển tiếp mã cũ 13840 sang 121063 và 5759 sang 33131 nếu có trong maps
      if (prodId && maps[prodId]) {
        if (maps[prodId].sourceProdId === "13840" || maps[prodId].sourceProdId === "138400") {
          maps[prodId].sourceProdId = "121063";
          maps[prodId].sourcePrice = 656;
          maps[prodId].sourceStock = 88181;
        }
        if (maps[prodId].sourceProdId === "5759") {
          maps[prodId].sourceProdId = "33131";
          maps[prodId].sourcePrice = 2400;
          maps[prodId].sourceStock = 2715;
        }
      }

      // 1. Kiểm tra cấu hình explicitly bị tắt
      if (prodId && maps[prodId] && maps[prodId].enabled === false) {
        return null;
      }

      // ƯU TIÊN SỐ 1: Cấu hình mới nhất do Admin thiết lập trong bảng maps / localStorage
      if (prodId && maps[prodId] && maps[prodId].enabled && maps[prodId].sourceProdId) {
        return enrichMapping(maps[prodId]);
      }
      if (prodObj && prodObj.id && maps[prodObj.id] && maps[prodObj.id].enabled && maps[prodObj.id].sourceProdId) {
        return enrichMapping(maps[prodObj.id]);
      }

      // ƯU TIÊN SỐ 2: Tra cứu theo khóa sao lưu độc lập mmo_api_map_[id]
      try {
        const storedMap = (prodId ? localStorage.getItem("mmo_api_map_" + prodId) : null) || (prodObj && prodObj.id ? localStorage.getItem("mmo_api_map_" + prodObj.id) : null);
        if (storedMap) {
          const parsedM = JSON.parse(storedMap);
          if (parsedM && parsedM.enabled && parsedM.sourceProdId) {
            return enrichMapping(parsedM);
          }
        }
      } catch(e) {}

      // ƯU TIÊN SỐ 3: apiMapping gắn trực tiếp trên đối tượng sản phẩm (nếu có và hợp lệ)
      if (prodObj && prodObj.apiMapping && prodObj.apiMapping.enabled && prodObj.apiMapping.sourceProdId) {
        return enrichMapping(prodObj.apiMapping);
      }
      if (prodObj && Array.isArray(prodObj.variants) && prodObj.variants.length > 0) {
        for (const v of prodObj.variants) {
          if (v && v.apiMapping && v.apiMapping.enabled && v.apiMapping.sourceProdId) {
            return enrichMapping(v.apiMapping);
          }
        }
      }

      // ƯU TIÊN SỐ 4: Fallback defaultMappings
      if (prodId && defaultMappings[prodId]) {
        return enrichMapping(defaultMappings[prodId]);
      }
      if (prodObj && prodObj.id && defaultMappings[prodObj.id]) {
        return enrichMapping(defaultMappings[prodObj.id]);
      }

      // 4. Tra cứu theo tên sản phẩm (CHỈ khi tham số truyền vào là chuỗi tên, TUYỆT ĐỐI không áp dụng khi là mã ID)
      if (!isIdKey && prodName) {
        const lowerPN = prodName.toLowerCase().trim();
        const isGenericName = ["default", "gói 1", "gói 2", "gói 3", "gói 4", "hotmail live", "mail 24h", "mặc định"].includes(lowerPN);
        if (!isGenericName) {
          if (maps[prodName] && maps[prodName].enabled && maps[prodName].sourceProdId) {
            return enrichMapping(maps[prodName]);
          }
          const normN = normApiText(prodName);
          for (const k of Object.keys(maps)) {
            const m = maps[k];
            if (m && m.enabled && m.sourceProdId) {
              if (m.targetProdName && normApiText(m.targetProdName) === normN && normN.length > 5) return enrichMapping(m);
            }
          }
        }
      }

      // 5. Nếu đối tượng có deliveryType === 'api', tra cứu alias hoặc key con
      if (prodObj && (prodObj.deliveryType === 'api' || prodObj.delivery_type === 'api')) {
        for (const k of Object.keys(maps)) {
          const m = maps[k];
          if (m && m.enabled && m.sourceProdId) {
            if (k.startsWith(prodObj.id)) return enrichMapping(m);
          }
        }
      }

      // 6. Tra cứu trong defaultMappings built-in nếu chưa được cấu hình thủ công
      if (prodId && defaultMappings[prodId]) {
        return enrichMapping(defaultMappings[prodId]);
      }
      if (prodObj && prodObj.id && defaultMappings[prodObj.id]) {
        return enrichMapping(defaultMappings[prodObj.id]);
      }

      return null;
    }
    window.getApiProductMapping = getApiProductMapping;

