    // PREVIEW & UPLOAD BRAND IMAGES (LOGO, FAVICON, OG IMAGE)
    function previewBrandUrl(url, previewId, hintId, resetBtnId) {
      const preview = document.getElementById(previewId);
      const hint = document.getElementById(hintId);
      const resetBtn = document.getElementById(resetBtnId);
      const cleanUrl = (url || "").trim();
      if (preview) {
        if (cleanUrl) {
          preview.onerror = function() {
            if (hint) {
              hint.innerText = "⚠️ Link ảnh lỗi hoặc không tải được!";
              hint.style.display = "inline-block";
              hint.style.color = "#ef4444";
            }
          };
          preview.onload = function() {
            if (hint) hint.style.display = "none";
          };
          preview.src = cleanUrl;
          preview.style.display = "block";
          if (hint) hint.style.display = "none";
          if (resetBtn) resetBtn.style.display = "inline-block";
        } else {
          preview.src = "";
          preview.style.display = "none";
          if (hint) {
            hint.style.display = "inline-block";
            hint.style.color = "#64748b";
          }
          if (resetBtn) resetBtn.style.display = "none";
        }
      }
    }
    window.previewBrandUrl = previewBrandUrl;

    async function uploadBase64ToCdn(dataUrl, name) {
      if (!dataUrl || typeof dataUrl !== "string" || !dataUrl.startsWith("data:image/")) return dataUrl;
      try {
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
        const tId = ctrl ? setTimeout(() => { try { ctrl.abort(); } catch(e){} }, 5000) : null;
        const res = await fetch("https://mmo-shop-api.khotaikhoanso-net.workers.dev/api/upload-image", {
          method: "POST",
          signal: ctrl ? ctrl.signal : undefined,
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            image: dataUrl,
            mimeType: dataUrl.indexOf("data:image/png") !== -1 ? "image/png" : "image/jpeg",
            name: name || "brand_asset.png"
          })
        });
        if (tId) clearTimeout(tId);
        const d = await res.json();
        // Chỉ chấp nhận link CDN công khai như iili.io, KHÔNG nhận link workers.dev vì bị Chrome chặn Lookalike
        if (d && d.success && d.url && !d.url.includes("workers.dev")) return d.url;
      } catch(e) {
        console.warn("Upload base64 to CDN notice:", e);
      }
      return dataUrl;
    }
    window.uploadBase64ToCdn = uploadBase64ToCdn;

    function handleUploadBrandFile(e, inputId, previewId, hintId, resetBtnId) {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      if (file.size > 15 * 1024 * 1024) {
        if (typeof showToast === "function") showToast("⚠️ Kích thước ảnh quá lớn! Vui lòng chọn ảnh dưới 15MB.", "warning");
        return;
      }
      if (typeof showToast === "function") showToast("⏳ Đang xử lý và lưu ảnh...", "info");

      // 1. Dùng FileReader & Canvas để nén và resize ảnh siêu nét, siêu nhẹ chống tràn bộ nhớ
      const reader = new FileReader();
      reader.onload = function(evt) {
        const rawDataUrl = evt.target.result;
        const img = new Image();
        img.onload = async function() {
          try {
            const isLogo = String(inputId).toLowerCase().includes("logo");
            const isFavicon = String(inputId).toLowerCase().includes("favicon");

            let maxW = 400;
            let maxH = 140;
            if (isFavicon) {
              maxW = 64;
              maxH = 64;
            } else if (!isLogo) {
              maxW = 1200;
              maxH = 630;
            }

            let width = img.width;
            let height = img.height;
            if (width > maxW || height > maxH) {
              const ratio = Math.min(maxW / width, maxH / height);
              width = Math.round(width * ratio);
              height = Math.round(height * ratio);
            }

            const canvas = document.createElement("canvas");
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext("2d");
            ctx.drawImage(img, 0, 0, width, height);

            // Xuất compact base64
            const mimeType = (file.type && file.type.includes("png")) ? "image/png" : "image/jpeg";
            const compactDataUrl = canvas.toDataURL(mimeType, 0.86);

            // Cập nhật preview và gán vào ô input ngay lập tức
            const input = document.getElementById(inputId);
            if (input) input.value = compactDataUrl;
            previewBrandUrl(compactDataUrl, previewId, hintId, resetBtnId);

            // Cập nhật DOM Logo nếu là Logo
            if (isLogo) {
              document.querySelectorAll(".logo img, .logo-img, img.logo-img, #headerSiteLogo, #footerSiteLogo, #drawerSiteLogo").forEach(function(el){ el.src = compactDataUrl; });
            }

            // TỰ ĐỘNG LƯU NGAY LẬP TỨC VÀO LOCALSTORAGE
            const curSettings = getGeneralSettings();
            if (isLogo) curSettings.brandLogo = compactDataUrl;
            else if (isFavicon) curSettings.brandFavicon = compactDataUrl;
            else curSettings.brandOgImage = compactDataUrl;
            curSettings._lastSavedAt = Date.now();

            try { localStorage.setItem("mmo_system_settings", JSON.stringify(curSettings)); } catch(e1) {}
            try { localStorage.setItem("mmo_general_settings", JSON.stringify(curSettings)); } catch(e2) {}
            try { localStorage.setItem("khotaikhoanso_settings", JSON.stringify(curSettings)); } catch(e3) {}
            try { localStorage.setItem("mmo_settings_permanent_backup", JSON.stringify(curSettings)); } catch(e4) {}

            applyBrandCustomizations(curSettings);

            // 2. Tải lên máy chủ để lấy URL iili.io CDN nếu có thể (chống chặn Lookalike)
            try {
              const cdnUrl = await uploadBase64ToCdn(compactDataUrl, file.name);
              if (cdnUrl && cdnUrl.startsWith("http") && !cdnUrl.includes("workers.dev")) {
                if (input) input.value = cdnUrl;
                previewBrandUrl(cdnUrl, previewId, hintId, resetBtnId);
                if (isLogo) curSettings.brandLogo = cdnUrl;
                else if (isFavicon) curSettings.brandFavicon = cdnUrl;
                else curSettings.brandOgImage = cdnUrl;

                try { localStorage.setItem("mmo_system_settings", JSON.stringify(curSettings)); } catch(e1) {}
                try { localStorage.setItem("mmo_general_settings", JSON.stringify(curSettings)); } catch(e2) {}
                try { localStorage.setItem("khotaikhoanso_settings", JSON.stringify(curSettings)); } catch(e3) {}
                try { localStorage.setItem("mmo_settings_permanent_backup", JSON.stringify(curSettings)); } catch(e4) {}
              }
            } catch(eUpload) { console.warn("Background upload error:", eUpload); }

            // Lưu lên Turso Cloud Worker
            const ktsBrandPayload = {
              kts_brandLogo: curSettings.brandLogo || "",
              kts_brandFavicon: curSettings.brandFavicon || "",
              kts_brandOgImage: curSettings.brandOgImage || "",
              khotaikhoanso_settings: JSON.stringify(curSettings)
            };
            fetch("https://mmo-shop-api.khotaikhoanso-net.workers.dev/api/admin/settings", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ settings: ktsBrandPayload })
            }).catch(function(){});

            if (typeof showToast === "function") showToast("🎉 Tải ảnh và lưu thành công!", "success");
          } catch(errCanvas) {
            console.error("Canvas compression error:", errCanvas);
            fallbackLocalBrandUpload(file, inputId, previewId, hintId, resetBtnId);
          }
        };
        img.onerror = function() {
          fallbackLocalBrandUpload(file, inputId, previewId, hintId, resetBtnId);
        };
        img.src = rawDataUrl;
      };
      reader.readAsDataURL(file);
    }
    function fallbackLocalBrandUpload(file, inputId, previewId, hintId, resetBtnId) {
      const reader = new FileReader();
      reader.onload = function(evt) {
        const dataUrl = evt.target.result;
        const input = document.getElementById(inputId);
        if (input) input.value = dataUrl;
        previewBrandUrl(dataUrl, previewId, hintId, resetBtnId);
        if (typeof showToast === "function") showToast("✅ Đã lưu ảnh thành công!", "success");
      };
      reader.readAsDataURL(file);
    }
    window.handleUploadBrandFile = handleUploadBrandFile;

    function resetBrandField(type) {
      if (type === "logo") {
        const inp = document.getElementById("setSiteLogoUrl");
        if (inp) inp.value = "https://iili.io/nGs8AOJ.png";
        previewBrandUrl("https://iili.io/nGs8AOJ.png", "setSiteLogoPreview", "setSiteLogoHint", "btnResetLogo");
      } else if (type === "favicon") {
        const inp = document.getElementById("setSiteFaviconUrl");
        if (inp) inp.value = "https://iili.io/nGsvaae.png";
        previewBrandUrl("https://iili.io/nGsvaae.png", "setSiteFaviconPreview", "setSiteFaviconHint", "btnResetFavicon");
      } else if (type === "ogImage") {
        const inp = document.getElementById("setSiteOgImageUrl");
        if (inp) inp.value = "https://iili.io/nGs8RDv.jpg";
        previewBrandUrl("https://iili.io/nGs8RDv.jpg", "setSiteOgImagePreview", "setSiteOgImageHint", "btnResetOgImage");
      }
    }
    window.resetBrandField = resetBrandField;

    // ÁP DỤNG THƯƠNG HIỆU LÊN TOÀN TRANG (LOGO, FAVICON, TIÊU ĐỀ)
    function applyBrandCustomizations(s) {
      try {
        const settings = s || getGeneralSettings();
        if (!settings) return;

        // 1. Tên sàn
        if (settings.siteName) {
          const siteNameEl = document.getElementById("headerSiteName");
          if (siteNameEl) siteNameEl.innerText = settings.siteName;
          document.title = settings.siteName + " - Kho Tài Khoản Số & Dịch Vụ MMO Uy Tín";
        }

        // 2. Logo Header, Footer, Drawer & Toàn Bộ Trang
        const cleanLogo = (settings.brandLogo && settings.brandLogo.trim() && !settings.brandLogo.includes("workers.dev")) 
          ? settings.brandLogo.trim() 
          : "https://iili.io/nGs8AOJ.png";
        document.querySelectorAll(".logo img, .logo-img, img.logo-img, .header-inner .logo img, .footer-col-1 .logo img, .footer-col-1 .logo-img, .mobile-drawer-header .logo-img, #headerSiteLogo, #footerSiteLogo, #drawerSiteLogo").forEach(function(img) {
          img.src = cleanLogo;
        });

        // Đảm bảo toàn bộ Logo Website có href='/' hợp lệ
        document.querySelectorAll(".logo, .header-inner .logo, .footer-col-1 .logo").forEach(function(a) {
          if (!a.getAttribute("href") || a.getAttribute("href") === "javascript:void(0)" || a.getAttribute("href") === "#") {
            a.setAttribute("href", "/");
          }
          a.onclick = function(event) {
            if (!event.ctrlKey && !event.metaKey && event.button === 0) {
              event.preventDefault();
              if (typeof switchView === "function") switchView("viewStore");
            }
          };
        });

        // 3. Favicon Website
        const cleanFavicon = (settings.brandFavicon && settings.brandFavicon.trim() && !settings.brandFavicon.includes("workers.dev")) 
          ? settings.brandFavicon.trim() 
          : "https://iili.io/nGsvaae.png";
        document.querySelectorAll("link[rel*='icon']").forEach(function(el) { el.remove(); });
        const favLink = document.createElement("link");
        favLink.rel = "shortcut icon";
        favLink.type = "image/png";
        favLink.href = cleanFavicon;
        document.head.appendChild(favLink);

        // 4. Ảnh OG Image
        const cleanOg = (settings.brandOgImage && settings.brandOgImage.trim() && !settings.brandOgImage.includes("workers.dev") && !settings.brandOgImage.includes("nFV4Rln.png")) 
          ? settings.brandOgImage.trim() 
          : "https://iili.io/nGs8RDv.jpg";
        let ogMeta = document.querySelector("meta[property='og:image']");
        if (ogMeta) ogMeta.setAttribute("content", cleanOg);
        let ogSec = document.querySelector("meta[property='og:image:secure_url']");
        if (ogSec) ogSec.setAttribute("content", cleanOg);
        let twMeta = document.querySelector("meta[name='twitter:image']");
        if (twMeta) twMeta.setAttribute("content", cleanOg);

        // 5. Đồng bộ Hotline / Zalo toàn trang
        if (typeof syncZaloLinks === "function") {
          syncZaloLinks(settings.hotline);
        }
      } catch(e) {
        console.error("applyBrandCustomizations error:", e);
      }
    }
    window.applyBrandCustomizations = applyBrandCustomizations;

    async function syncSettingsFromCloud() {
      try {
        const res = await fetch("https://mmo-shop-api.khotaikhoanso-net.workers.dev/api/admin/settings");
        if (!res.ok) return;
        const data = await res.json();
        if (data && data.success && data.settings && typeof data.settings === "object") {
          const cs = data.settings;
          const _aiProviders = ['groq', 'cerebras', 'openrouter', 'gemini', 'nvidia', 'mistral'];
          _aiProviders.forEach(function(p) {
            const cloudKey = cs['ai_key_' + p] || cs['mmo_ai_key_' + p];
            if (cloudKey && typeof MMO_AI_KEYS !== 'undefined') {
              const current = MMO_AI_KEYS.get(p);
              if (!current || (p === 'gemini' && current === 'AIzaSyC9sF4GpjjE3maBpVDi35wVIrsaPbZ3EZg' && cloudKey !== current)) {
                MMO_AI_KEYS.set(p, cloudKey);
                const el = document.getElementById('setAiKey' + p.charAt(0).toUpperCase() + p.slice(1));
                if (el && !el.value) el.value = cloudKey;
              }
            }
          });

          // ĐỒNG BỘ THƯƠNG HIỆU TỪ NAMESPACE CÁCH LY kts_* TRÊN TURSO CLOUD DATABASE
          const curSettings = getGeneralSettings();
          let settingsChanged = false;

          if (cs.kts_brandLogo && cs.kts_brandLogo.trim() && !cs.kts_brandLogo.includes("workers.dev")) {
            curSettings.brandLogo = cs.kts_brandLogo.trim();
            settingsChanged = true;
            const logoInp = document.getElementById("setSiteLogoUrl");
            if (logoInp && document.activeElement !== logoInp) logoInp.value = curSettings.brandLogo;
            previewBrandUrl(curSettings.brandLogo, "setSiteLogoPreview", "setSiteLogoHint", "btnResetLogo");
          }
          if (cs.kts_brandFavicon && cs.kts_brandFavicon.trim() && !cs.kts_brandFavicon.includes("workers.dev")) {
            curSettings.brandFavicon = cs.kts_brandFavicon.trim();
            settingsChanged = true;
            const favInp = document.getElementById("setSiteFaviconUrl");
            if (favInp && document.activeElement !== favInp) favInp.value = curSettings.brandFavicon;
            previewBrandUrl(curSettings.brandFavicon, "setSiteFaviconPreview", "setSiteFaviconHint", "btnResetFavicon");
          }
          if (cs.kts_brandOgImage && cs.kts_brandOgImage.trim() && !cs.kts_brandOgImage.includes("workers.dev") && !cs.kts_brandOgImage.includes("nFV4Rln.png")) {
            curSettings.brandOgImage = cs.kts_brandOgImage.trim();
            settingsChanged = true;
            const ogInp = document.getElementById("setSiteOgImageUrl");
            if (ogInp && document.activeElement !== ogInp) ogInp.value = curSettings.brandOgImage;
            previewBrandUrl(curSettings.brandOgImage, "setSiteOgImagePreview", "setSiteOgImageHint", "btnResetOgImage");
          }
          if (cs.kts_siteName && cs.kts_siteName.trim()) {
            curSettings.siteName = cs.kts_siteName.trim();
            settingsChanged = true;
            const nameInp = document.getElementById("setSiteName");
            if (nameInp && document.activeElement !== nameInp) nameInp.value = curSettings.siteName;
          }
          if (cs.kts_hotline && cs.kts_hotline.trim()) {
            curSettings.hotline = cs.kts_hotline.trim();
            settingsChanged = true;
            const hotInp = document.getElementById("setHotline");
            if (hotInp && document.activeElement !== hotInp) hotInp.value = curSettings.hotline;
          }
          if (cs.kts_telegramGroup && cs.kts_telegramGroup.trim()) {
            curSettings.telegramGroup = cs.kts_telegramGroup.trim();
            settingsChanged = true;
            const teleGrpInp = document.getElementById("setTelegramGroup");
            if (teleGrpInp && document.activeElement !== teleGrpInp) teleGrpInp.value = curSettings.telegramGroup;
          }
          if (cs.kts_telegram && cs.kts_telegram.trim()) {
            curSettings.telegram = cs.kts_telegram.trim();
            settingsChanged = true;
            const teleInp = document.getElementById("setTelegram");
            if (teleInp && document.activeElement !== teleInp) teleInp.value = curSettings.telegram;
          }
          if (cs.kts_marqueeText && cs.kts_marqueeText.trim()) {
            curSettings.marqueeText = cs.kts_marqueeText.trim();
            settingsChanged = true;
            const marqInp = document.getElementById("setMarqueeText");
            if (marqInp && document.activeElement !== marqInp) marqInp.value = curSettings.marqueeText;
          }
          if (cs.kts_gasUrl && cs.kts_gasUrl.trim()) {
            curSettings.gasUrl = cs.kts_gasUrl.trim();
            settingsChanged = true;
            const gasInp = document.getElementById("setGasUrl");
            if (gasInp && (!gasInp.value || gasInp.value.trim() === "")) gasInp.value = curSettings.gasUrl;
          }

          if (settingsChanged) {
            try { localStorage.setItem("mmo_system_settings", JSON.stringify(curSettings)); } catch(e1) {}
            try { localStorage.setItem("mmo_general_settings", JSON.stringify(curSettings)); } catch(e2) {}
            try { localStorage.setItem("mmo_settings_permanent_backup", JSON.stringify(curSettings)); } catch(e3) {}
            try { localStorage.setItem("khotaikhoanso_settings", JSON.stringify(curSettings)); } catch(e4) {}
          }
          applyBrandCustomizations(curSettings);
          if (typeof syncContactInfoToUI === "function") {
            syncContactInfoToUI();
          }
        }
      } catch(e) {}
    }
    window.syncSettingsFromCloud = syncSettingsFromCloud;

