    function switchProductDescTab(tabKey, btnElement) {
      const secDesc = document.getElementById("dtlTabSecDesc");
      const secGuide = document.getElementById("dtlTabSecGuide");
      const secReviews = document.getElementById("dtlTabSecReviews");
      const secApi = document.getElementById("dtlTabSecApi");

      if (secDesc) secDesc.style.display = (tabKey === "desc") ? "block" : "none";
      if (secGuide) secGuide.style.display = (tabKey === "guide") ? "block" : "none";
      if (secReviews) secReviews.style.display = (tabKey === "reviews") ? "block" : "none";
      if (secApi) secApi.style.display = (tabKey === "api") ? "block" : "none";

      const btnDesc = document.getElementById("dtlTabBtnDesc");
      const btnGuide = document.getElementById("dtlTabBtnGuide");
      const btnReviews = document.getElementById("dtlTabBtnReviews");
      const btnApi = document.getElementById("dtlTabBtnApi");

      [btnDesc, btnGuide, btnReviews, btnApi].forEach(b => {
        if (b) b.classList.remove("active");
      });

      if (btnElement && btnElement.classList) {
        btnElement.classList.add("active");
      } else {
        if (tabKey === "desc" && btnDesc) btnDesc.classList.add("active");
        if (tabKey === "guide" && btnGuide) btnGuide.classList.add("active");
        if (tabKey === "reviews" && btnReviews) btnReviews.classList.add("active");
        if (tabKey === "api" && btnApi) btnApi.classList.add("active");
      }

      if (tabKey === "reviews") {
        renderProductReviews();
      } else if (tabKey === "api") {
        if (typeof renderProductApiIntegration === "function") renderProductApiIntegration();
      }
    }
    window.switchProductDescTab = switchProductDescTab;

    // Dữ liệu đánh giá mặc định chất lượng cao cho sản phẩm MMO
    const DEFAULT_MMO_REVIEWS = [
      { name: "hoangnam***@gmail.com", rating: 5, date: "Hôm qua", comment: "Tài khoản chất lượng, đúng mô tả, đăng nhập mượt không bị checkpoint. Ủng hộ shop lâu dài!" },
      { name: "mmo_pro_99", rating: 5, date: "2 ngày trước", comment: "Giao hàng tự động trong 5 giây, có đầy đủ 2FA và mail khôi phục. Rất uy tín." },
      { name: "tranthanh***@yahoo.com", rating: 5, date: "3 ngày trước", comment: "Support nhiệt tình, tài khoản ngâm lâu form rất cứng. Chạy ads ngon lành." },
      { name: "vanhuy_agency", rating: 5, date: "4 ngày trước", comment: "Đã mua nhiều lần bên shop, chế độ bảo hành 1-đổi-1 nhanh chóng nên rất yên tâm." },
      { name: "lequocanh***@gmail.com", rating: 5, date: "5 ngày trước", comment: "Đúng hàng chuẩn, giá rẻ hơn thị trường mà chất lượng vượt mong đợi." },
      { name: "duy_marketing", rating: 5, date: "1 tuần trước", comment: "Acc dùng rất bền, login proxy sạch là dùng vĩnh viễn luôn. 5 sao!" }
    ];

    function getProductReviews(prodId) {
      try {
        const stored = localStorage.getItem("mmo_product_reviews_" + prodId);
        if (stored) {
          const parsed = JSON.parse(stored);
          if (Array.isArray(parsed) && parsed.length > 0) return parsed;
        }
      } catch(e) {}
      return DEFAULT_MMO_REVIEWS;
    }
    window.getProductReviews = getProductReviews;

    function renderProductReviews() {
      const listContainer = document.getElementById("dtlReviewsList");
      if (!listContainer) return;

      const pId = currentSelectedProduct ? currentSelectedProduct.id : "default";
      const reviews = getProductReviews(pId);

      const countTabEl = document.getElementById("dtlReviewsCountTab");
      const totalReviewsText = document.getElementById("dtlTotalReviewsText");
      if (countTabEl) countTabEl.innerText = reviews.length;
      if (totalReviewsText) totalReviewsText.innerText = reviews.length;

      listContainer.innerHTML = reviews.map(r => {
        let starsHtml = "";
        for (let i = 1; i <= 5; i++) {
          starsHtml += (i <= r.rating) 
            ? '<i class="fa-solid fa-star" style="color:#fbbf24; font-size:0.8rem; margin-right:2px;"></i>' 
            : '<i class="fa-regular fa-star" style="color:#475569; font-size:0.8rem; margin-right:2px;"></i>';
        }
        return `
          <div style="background:#070d18; border:1px solid #1e293b; border-radius:8px; padding:12px 14px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; flex-wrap:wrap; gap:6px;">
              <div style="display:flex; align-items:center; gap:8px;">
                <div style="width:28px; height:28px; border-radius:50%; background:linear-gradient(135deg, #10b981, #06b6d4); color:#fff; display:flex; align-items:center; justify-content:center; font-size:0.75rem; font-weight:700;">
                  ${(r.name || 'U').charAt(0).toUpperCase()}
                </div>
                <strong style="color:#f1f5f9; font-size:0.85rem;">${escapeHtml(r.name || 'Khách hàng')}</strong>
                <span style="background:rgba(16,185,129,0.15); color:#10b981; font-size:0.68rem; padding:1px 6px; border-radius:4px; font-weight:700;">
                  <i class="fa-solid fa-check"></i> Đã mua hàng
                </span>
              </div>
              <span style="font-size:0.75rem; color:#64748b;">${escapeHtml(r.date || 'Gần đây')}</span>
            </div>
            <div style="margin-bottom:6px;">${starsHtml}</div>
            <p style="color:#cbd5e1; font-size:0.82rem; margin:0; line-height:1.5;">${escapeHtml(r.comment || 'Sản phẩm rất tốt!')}</p>
          </div>
        `;
      }).join("");
    }
    window.renderProductReviews = renderProductReviews;

    function showWriteReviewPrompt() {
      const ratingStr = prompt("⭐ Bạn muốn đánh giá sản phẩm mấy sao? (Nhập từ 1 đến 5 sao):", "5");
      if (ratingStr === null) return;
      const stars = parseInt(ratingStr) || 5;
      const validStars = Math.max(1, Math.min(5, stars));

      const comment = prompt("✍ Nhập nội dung đánh giá hoặc cảm nhận của bạn về sản phẩm:", "Tài khoản chất lượng tốt, giao nhanh và uy tín!");
      if (!comment || !comment.trim()) return;

      const pId = currentSelectedProduct ? currentSelectedProduct.id : "default";
      const reviews = [...getProductReviews(pId)];

      const userEmail = (typeof currentUser !== "undefined" && currentUser && currentUser.email) 
        ? (currentUser.email.split("@")[0].substring(0, 5) + "***@" + (currentUser.email.split("@")[1] || "gmail.com"))
        : "khachhang_" + Math.floor(Math.random() * 1000) + "@gmail.com";

      reviews.unshift({
        name: userEmail,
        rating: validStars,
        date: "Vừa xong",
        comment: comment.trim()
      });

      try {
        localStorage.setItem("mmo_product_reviews_" + pId, JSON.stringify(reviews));
      } catch(e) {}

      renderProductReviews();
      showToast("Cảm ơn bạn đã gửi đánh giá " + validStars + "⭐ cho sản phẩm!", "success");
    }
    window.showWriteReviewPrompt = showWriteReviewPrompt;


    function selectVariant(idx, price) {
      currentSelectedVariantIndex = idx;
      currentSelectedPrice = price;
      const dtlPrice = document.getElementById("dtlPrice");
      if (dtlPrice) dtlPrice.innerText = formatVND(price);
      document.querySelectorAll(".variant-pill-option").forEach((el, i) => {
        el.classList.toggle("active", i === idx);
      });

      // [UNIFIED WAREHOUSE CORE]: Cập nhật tình trạng kho của đúng biến thể vừa chọn
      let vStock = 0;
      if (currentSelectedProduct) {
        vStock = getShopVariantStock(currentSelectedProduct, idx);
        syncDetailStockUI(vStock);
        refreshAllShopStockUI(currentSelectedProduct.id);

        // Cập nhật lại hoa hồng theo giá biến thể vừa chọn (chống NaN%)
        let commRate = 10;
        if (currentSelectedProduct) {
          if (typeof currentSelectedProduct.commissionRate === "number" && !isNaN(currentSelectedProduct.commissionRate)) commRate = currentSelectedProduct.commissionRate;
          else if (typeof currentSelectedProduct.commission === "number" && !isNaN(currentSelectedProduct.commission)) commRate = currentSelectedProduct.commission;
          else {
            const m = String(currentSelectedProduct.commission || currentSelectedProduct.commissionRate || "").match(/[0-9]+/);
            commRate = m ? parseInt(m[0], 10) : 10;
          }
        }
        if (isNaN(commRate) || commRate <= 0) commRate = 10;
        const commVal = Math.round(Number(price || 0) * commRate / 100);
        const commFooterEl = document.getElementById("dtlCommissionFooterText");
        if (commFooterEl) {
          commFooterEl.innerText = "$ Hoa hồng: " + commRate + "% (~" + formatVND(commVal) + ")";
        }
      }
    }
    window.selectVariant = selectVariant;

    function changeDtlQty(delta) {
      const input = document.getElementById("dtlQtyInput");
      if (!input) return;
      let val = parseInt(input.value) || 1;
      const stock = currentSelectedProduct ? (typeof getProductStockCount === "function" ? getProductStockCount(currentSelectedProduct) : (currentSelectedProduct.stock || 99)) : 99;
      val = Math.max(1, Math.min(val + delta, stock > 0 ? stock : 1));
      input.value = val;
    }
    window.changeDtlQty = changeDtlQty;

    function applyCoupon() {
      const input = document.getElementById("dtlCouponInput");
      const code = input ? input.value.trim().toUpperCase() : "";
      if (!code) {
        showToast("Vui lòng nhập mã giảm giá!", "warning");
        return;
      }
      if (code === "MMO2026" || code === "GIAM10") {
        window.currentAppliedDiscount = 10;
        showToast("Áp dụng mã thành công! Giảm ngay 10% trên đơn hàng.", "success");
        if (currentSelectedProduct) {
          const variants = (currentSelectedProduct.variants && currentSelectedProduct.variants.length > 0) ? currentSelectedProduct.variants : [{ price: currentSelectedProduct.price }];
          const basePrice = Number(variants[currentSelectedVariantIndex]?.price || currentSelectedProduct.price || 0);
          const discPrice = Math.round(basePrice * 0.9);
          const dtlPrice = document.getElementById("dtlPrice");
          if (dtlPrice) dtlPrice.innerHTML = '<span style="text-decoration:line-through; color:#94a3b8; font-size:0.9rem; margin-right:8px;">' + formatVND(basePrice) + '</span> ' + formatVND(discPrice);
        }
      } else {
        showToast("Mã giảm giá không hợp lệ hoặc đã hết hạn!", "danger");
      }
    }
    window.applyCoupon = applyCoupon;

    
    // ==================== EXECUTE BUY NOW FLOW ====================
    async function executeBuyCurrentProduct() {
    const btnBuy = document.getElementById("btnDtlBuy");
    let prevBtnContent = "";
    if (btnBuy) {
      if (!btnBuy.dataset) btnBuy.dataset = {};
      if (btnBuy.dataset.submitting === "true") return;
    }

    // 0. Khôi phục sản phẩm đang xem
    let p = currentSelectedProduct;
    if (!p) {
      let prodParam = null;
      try {
        if (typeof URLSearchParams !== "undefined" && window.location && window.location.search) {
          prodParam = new URLSearchParams(window.location.search).get("prod");
        }
      } catch(e) {}
      if (prodParam && typeof findShopProduct === "function") {
        p = findShopProduct(prodParam);
      }
      currentSelectedProduct = p;
    }

    // NẾU HẾT HÀNG (STOCK <= 0) -> CHUYỂN NGAY SANG ĐẶT TRƯỚC
    const hasVarsCheck = p && Array.isArray(p.variants) && p.variants.length > 0;
    const vIdxCheck = (typeof currentSelectedVariantIndex !== "undefined" && currentSelectedVariantIndex !== null) ? Number(currentSelectedVariantIndex) : 0;
    const currentStockCheck = (p && typeof getShopVariantStock === "function") ? getShopVariantStock(p, vIdxCheck) : (p ? (p.stock || 0) : 0);
    if (currentStockCheck <= 0) {
      if (typeof openPreOrderModal === "function") {
        openPreOrderModal(p, vIdxCheck);
      }
      return;
    }

    if (btnBuy) {
      btnBuy.dataset.submitting = "true";
      prevBtnContent = btnBuy.innerHTML;
      btnBuy.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang xử lý đơn hàng...";
      btnBuy.style.opacity = "0.75";
      btnBuy.style.pointerEvents = "none";
    }
    const restoreBtn = () => {
      if (btnBuy) {
        if (!btnBuy.dataset) btnBuy.dataset = {};
        btnBuy.dataset.submitting = "false";
        btnBuy.innerHTML = prevBtnContent || "<i class='fa-solid fa-bolt'></i> MUA NGAY";
        btnBuy.style.opacity = "1";
        btnBuy.style.pointerEvents = "auto";
      }
    };

    try {
      // 0. Khôi phục phiên đăng nhập nếu có
      if (!currentUser) {
        try {
          const storedUser = localStorage.getItem("mmo_user");
          if (storedUser) currentUser = JSON.parse(storedUser);
        } catch(e) {}
      }
      const cleanEmail = currentUser ? (currentUser.email || "").toLowerCase().trim() : "";
      let p = currentSelectedProduct;
      if (!p) {
        let prodParam = null;
        try {
          if (typeof URLSearchParams !== "undefined" && window.location && window.location.search) {
            prodParam = new URLSearchParams(window.location.search).get("prod");
          }
        } catch(e) {}
        if (prodParam && typeof MOCK_DATA !== "undefined" && MOCK_DATA.products) {
          p = findShopProduct(prodParam);
        }
        currentSelectedProduct = p;
      }

      if (!p) {
        restoreBtn();
        showToast("Không tìm thấy thông tin sản phẩm!", "danger");
        return;
      }

      const hasVars = Array.isArray(p.variants) && p.variants.length > 0;
      const vIdx = (typeof currentSelectedVariantIndex !== "undefined" && currentSelectedVariantIndex !== null) ? Number(currentSelectedVariantIndex) : 0;
      const targetVar = hasVars ? (p.variants[vIdx] || p.variants[0]) : p;
      const qtyInput = document.getElementById("dtlQtyInput");
      const qty = Math.max(1, parseInt(qtyInput ? qtyInput.value : "1") || 1);

      // Kiểm tra API On-Demand
      let apiMap = null;
      if (typeof getApiProductMapping === "function") {
        apiMap = getApiProductMapping(p) || (p && p.apiMapping);
        if (!apiMap || !apiMap.sourceProdId) {
          apiMap = getApiProductMapping(p.id + "_" + vIdx);
        }
        if (!apiMap || !apiMap.sourceProdId) {
          const vName = (targetVar && targetVar.name) ? targetVar.name : "";
          const lowerVN = vName.toLowerCase().trim();
          if (vName && !["default", "gói 1", "gói 2", "gói 3", "gói 4", "hotmail live", "mail 24h", "mặc định"].includes(lowerVN)) {
            apiMap = getApiProductMapping(vName);
          }
        }
      }
      const isApiOnDemand = !!(apiMap && apiMap.enabled && apiMap.sourceProdId);

      // Kiểm tra tồn kho
      const availableStock = typeof getShopVariantStock === "function"
        ? getShopVariantStock(p, hasVars ? vIdx : null)
        : (isApiOnDemand ? ((apiMap.sourceStock !== undefined && apiMap.sourceStock !== null) ? Number(apiMap.sourceStock) : (p.stock || 0)) : Math.max(Array.isArray(targetVar.accounts) ? targetVar.accounts.length : 0, Number(targetVar.stock) || 0));

      if (availableStock <= 0) {
        restoreBtn();
        showToast("⚠️ Biến thể này hiện đã HẾT HÀNG trong kho! Vui lòng chọn biến thể khác hoặc liên hệ Admin.", "danger");
        return;
      }
      if (!isApiOnDemand && qty > availableStock) {
        restoreBtn();
        showToast("⚠️ Số lượng tồn kho không đủ! Kho chỉ còn " + availableStock + " sản phẩm (bạn đang chọn " + qty + ").", "warning");
        return;
      }

      let unitPrice = Number(targetVar.price);
      if (isNaN(unitPrice) || unitPrice <= 0) {
        unitPrice = Number(p.price) || 0;
      }
      if (unitPrice <= 0 && !p.isFree && !targetVar.isFree) {
        restoreBtn();
        showToast("⚠️ Giá sản phẩm chưa hợp lệ (> 0đ)! Không thể thanh toán 0 đồng.", "danger");
        return;
      }
      if (window.currentAppliedDiscount > 0) {
        unitPrice = Math.round(unitPrice * (100 - window.currentAppliedDiscount) / 100);
      }
      const totalCost = unitPrice * qty;

      const orderId = "DH" + Math.floor(100000 + Math.random() * 900000);
      const curBal = (currentUser && Number(currentUser.balance)) || 0;

      // NẾU CHƯA ĐĂNG NHẬP: YÊU CẦU ĐĂNG NHẬP
      if (!currentUser) {
        restoreBtn();
        showToast("🔒 Vui lòng đăng nhập tài khoản để mua hàng!", "warning");
        if (typeof openAuthModal === "function") openAuthModal("login");
        return;
      }

      // NẾU SỐ DƯ VÍ KHÔNG ĐỦ: CHUYỂN HƯỚNG SANG NẠP TIỀN VÀO VÍ TIỀN
      if (curBal < totalCost) {
        restoreBtn();
        const missing = totalCost - curBal;
        const depositAmt = Math.max(10000, missing);
        showToast("⚠️ Số dư ví không đủ (Hiện có: " + formatVND(curBal) + " - Đơn hàng: " + formatVND(totalCost) + ")! Đang chuyển hướng sang nạp tiền...", "warning");

        if (typeof closeModal === "function") {
          closeModal("directPaymentModal");
          closeModal("orderDeliveryModal");
          closeModal("modalQuickBuy");
          closeModal("quickBuyModal");
        }

        try {
          localStorage.setItem("mmo_pending_order", JSON.stringify({
            prodId: p.id,
            vIdx: vIdx,
            qty: qty,
            needed: depositAmt
          }));
        } catch(e) {}

        window._targetDepositAmount = depositAmt;
        setTimeout(function() {
          if (typeof switchView === "function") {
            switchView("viewDeposit");
            if (typeof selectDepositAmount === "function") {
              selectDepositAmount(depositAmt);
            } else if (typeof prepareDeposit === "function") {
              prepareDeposit(depositAmt, true);
            }
            window.scrollTo({ top: 0, behavior: "smooth" });
          }
        }, 300);
        return;
      }
      let credsLines = [];
      let workerHandled = false;

      // [ƯU TIÊN TỐI CAO] GỌI TRỰC TIẾP CLOUDFLARE WORKER / TURSO ĐÁM MÂY XỬ LÝ 100%
      try {
        const workerCheckoutUrl = (typeof MMO_WORKER_API !== "undefined" && typeof MMO_WORKER_API.getApiUrl === "function")
          ? (MMO_WORKER_API.getApiUrl() + "/api/orders/checkout")
          : "https://mmo-shop-api.khotaikhoanso-net.workers.dev/api/orders/checkout";
        const reqHeaders = { "Content-Type": "application/json" };
        const sessionTok = (typeof localStorage !== "undefined" && (localStorage.getItem("mmo_session_token") || localStorage.getItem("mmo_admin_secret"))) || "";
        if (sessionTok) {
          reqHeaders["Authorization"] = "Bearer " + sessionTok;
          reqHeaders["x-session-token"] = sessionTok;
        }

        const checkoutPayload = {
          product_id: p.id,
          variant_idx: vIdx,
          quantity: qty,
          order_id: orderId,
          customer_email: cleanEmail,
          customer_name: (currentUser && (currentUser.name || currentUser.username)) || cleanEmail,
          amount: totalCost,
          payment_method: "BALANCE",
          api_mapping: isApiOnDemand ? apiMap : null
        };

        const wRes = await fetch(workerCheckoutUrl, {
          method: "POST",
          headers: reqHeaders,
          body: JSON.stringify(checkoutPayload)
        });

        const wData = await wRes.json().catch(() => null);
        if (wData && wData.success && Array.isArray(wData.accounts) && wData.accounts.length >= qty) {
          credsLines = wData.accounts;
          workerHandled = true;
          if (wData.balance_after !== undefined && !isNaN(Number(wData.balance_after))) {
            currentUser.balance = Number(wData.balance_after);
          }
        } else if (wData && !wData.success) {
          const errMsg = wData.message || "Kho hàng tạm thời không đủ số lượng tài khoản!";
          if (wData.code === "INSUFFICIENT_BALANCE") {
            restoreBtn();
            showToast("⚠️ " + errMsg, "warning");
            setTimeout(function() {
              if (typeof switchView === "function") switchView("viewDeposit");
            }, 600);
            return;
          }
          const isOutOfStock = /hết hàng|không đủ|out of stock|tồn kho|số lượng|không khả dụng/i.test(errMsg);
          if (isOutOfStock) {
            restoreBtn();
            if (isApiOnDemand && typeof markApiProductOutOfStock === "function") {
              markApiProductOutOfStock(p, vIdx, errMsg);
            }
            showToast("⚠️ " + errMsg + " Đang chuyển sang Đặt Trước...", "warning");
            if (typeof openPreOrderModal === "function") {
              setTimeout(() => openPreOrderModal(p, vIdx), 600);
            }
            return;
          }
          // Dừng và báo lỗi chính xác từ nhà cung cấp / Worker
          restoreBtn();
          showToast("⚠️ " + errMsg, "danger");
          return;
        }
      } catch(wErr) {
        console.warn("Worker direct checkout network fallback:", wErr);
      }

      // Fallback cục bộ chỉ khi Worker hoàn toàn không phản hồi hoặc ngoại tuyến
      if (!workerHandled) {
        if (isApiOnDemand) {
          const providerKey = apiMap.provider || "selltainguyenmmo";
          try {
            const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[providerKey]) ? API_SOURCES[providerKey] : { baseUrl: "https://selltainguyenmmo.com", apiKey: "" };
            const buyRes = await executeSourceApiCall("buyProduct", {
              productId: apiMap.sourceProdId,
              amount: qty,
              provider: providerKey,
              baseUrl: apiMap.baseUrl || pCfg.baseUrl,
              apiKey: apiMap.apiKey || pCfg.apiKey,
              username: apiMap.username || pCfg.username,
              password: apiMap.password || pCfg.password,
              targetProdId: p.id
            });
            if (buyRes && buyRes.success && Array.isArray(buyRes.accounts) && buyRes.accounts.length >= qty) {
              credsLines = buyRes.accounts;
            } else {
              restoreBtn();
              let errMsg = (buyRes && (buyRes.message || buyRes.msg)) || "Kho hàng đang cập nhật thêm tài khoản. Số dư của bạn chưa bị trừ!";
              if (errMsg.includes("Blocked invalid endpoint")) errMsg = "Máy chủ nguồn hàng API tạm thời đang xử lý, vui lòng thử lại!";
              const isOutOfStockOrBalance = /không đủ|hết hàng|out of stock|tồn kho|số lượng|balance|số dư|không khả dụng/i.test(errMsg);
              if (isOutOfStockOrBalance && typeof markApiProductOutOfStock === "function") {
                markApiProductOutOfStock(p, vIdx, errMsg);
                showToast("⚠️ Nhà cung cấp hiện đang hết hàng (" + errMsg + "). Sản phẩm đã chuyển sang [ĐẶT TRƯỚC]! Số dư ví của bạn không bị trừ.", "warning");
                if (typeof openPreOrderModal === "function") {
                  setTimeout(() => openPreOrderModal(p, vIdx), 800);
                }
              } else {
                showToast("⚠️ " + errMsg, "warning");
              }
              return;
            }
          } catch(apiErr) {
            restoreBtn();
            const realErrMsg = (apiErr && (apiErr.message || apiErr.msg)) ? String(apiErr.message || apiErr.msg) : "";
            showToast("⚠️ " + (realErrMsg || "Nguồn hàng API tạm thời không phản hồi. Vui lòng thử lại sau giây lát!"), "danger");
            return;
          }
        } else {
          let deliveredAccs = null;
          if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured() && typeof MMO_WORKER_API !== "undefined" && MMO_WORKER_API._checkWorkerAvailable()) {
            try {
              const tursoCreds = await TURSO_CLIENT.checkoutAccounts(p.id, vIdx, qty, orderId, cleanEmail, totalCost);
              if (tursoCreds && Array.isArray(tursoCreds) && tursoCreds.length >= qty) {
                deliveredAccs = tursoCreds;
                MMO_WAREHOUSE.deliverAccounts(p.id, vIdx, qty, orderId);
              }
            } catch(tursoBuyErr) {
              console.warn("Lỗi xuất kho Turso, chuyển sang kho nội bộ:", tursoBuyErr);
            }
          }

          if (!deliveredAccs || deliveredAccs.length < qty) {
            const localDelivered = MMO_WAREHOUSE.deliverAccounts(p.id, vIdx, qty, orderId);
            if (localDelivered && Array.isArray(localDelivered) && localDelivered.length >= qty) {
              deliveredAccs = localDelivered;
            }
          }

          if (deliveredAccs && deliveredAccs.length >= qty) {
            credsLines = deliveredAccs;
          } else {
            if (targetVar) {
              targetVar.stock = 0;
              targetVar.accounts = [];
            }
            refreshAllShopStockUI(p.id);
            if (typeof syncDetailStockUI === "function") syncDetailStockUI(0);
            restoreBtn();
            showToast("⚠️ Rất tiếc, kho hàng tạm thời không đủ số lượng tài khoản khả dụng!", "warning");
            if (typeof openPreOrderModal === "function") {
              setTimeout(() => openPreOrderModal(p, vIdx), 600);
            }
            return;
          }
        }
      }

      if (!credsLines || credsLines.length < qty) {
        restoreBtn();
        showToast("⚠️ Kho hàng không đủ tài khoản để giao!", "danger");
        return;
      }

      // TRỪ TIỀN VÍ NGƯỜI DÙNG
      const newBal = curBal - totalCost;
      currentUser.balance = newBal;
      try {
        localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        localStorage.setItem("mmo_last_balance_change_time", String(Date.now()));
        let allUsers = (typeof getRegisteredUsers === "function") ? getRegisteredUsers() : [];
        const uIdx = allUsers.findIndex(u => (u.email || "").toLowerCase().trim() === cleanEmail);
        if (uIdx !== -1) {
          allUsers[uIdx].balance = newBal;
          if (typeof saveRegisteredUsers === "function") saveRegisteredUsers(allUsers);
        }
      } catch(e) {}
      if (typeof updateUserUI === "function") updateUserUI();

      // GHI NHẬN BIẾN ĐỘNG SỐ DƯ (TRỪ TIỀN MUA HÀNG)
      const purchaseNote = "Mua SP: " + p.name + (targetVar.name && targetVar.name !== "Mặc định" ? " (" + targetVar.name + ")" : "") + " - Đơn #" + orderId;
      const purchaseNowTime = new Date().toLocaleDateString("vi-VN") + " " + new Date().toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });

      if (typeof recordTransaction === "function") {
        recordTransaction(
          cleanEmail,
          currentUser.name || cleanEmail,
          "Thanh toán mua hàng",
          -totalCost,
          newBal,
          purchaseNote
        );
      }

      try {
        const purchaseTxObj = {
          id: "ORD_" + orderId + "_" + Date.now(),
          txId: "ORD_" + orderId,
          orderId: orderId,
          userEmail: cleanEmail,
          userName: currentUser.name || cleanEmail,
          type: "Thanh toán mua hàng",
          amount: -totalCost,
          balanceAfter: newBal,
          note: purchaseNote,
          time: purchaseNowTime,
          date: purchaseNowTime
        };
        let mmoTxs = JSON.parse(localStorage.getItem("mmo_transactions") || "[]");
        mmoTxs.unshift(purchaseTxObj);
        localStorage.setItem("mmo_transactions", JSON.stringify(mmoTxs));
        localStorage.setItem("mmo_wallet_transactions", JSON.stringify(mmoTxs));
      } catch(e) {}

      // GHI NHẬN ĐƠN HÀNG HOÀN TOÀN MỚI
      const credsText = credsLines.join("\n");
      const nowTs = Date.now();
      const formattedNow = (typeof formatOrderDate === "function") ? formatOrderDate(null, nowTs) : new Date().toLocaleString("vi-VN");

      const orderObj = {
        id: orderId,
        orderId: orderId,
        orderCode: orderId,
        userEmail: cleanEmail,
        email: cleanEmail,
        buyerEmail: cleanEmail,
        username: (currentUser ? (currentUser.username || currentUser.name || cleanEmail) : cleanEmail) || "Khách Hàng",
        buyerUsername: (currentUser ? (currentUser.username || currentUser.name || cleanEmail) : cleanEmail) || "Khách Hàng",
        productId: p.id,
        productName: p.name,
        variant: (targetVar && targetVar.name) ? targetVar.name : "Mặc định",
        variantName: (targetVar && targetVar.name) ? targetVar.name : "Mặc định",
        quantity: qty,
        qty: qty,
        price: unitPrice,
        total: totalCost,
        totalPrice: totalCost,
        discount: window.currentAppliedDiscount || 0,
        credentials: credsText,
        deliveredAccounts: credsLines,
        accounts: credsLines,
        createdTimestamp: nowTs,
        createdAt: nowTs,
        date: formattedNow,
        status: "COMPLETED",
        statusText: "Hoàn thành",
        type: "REGULAR"
      };

      // Lưu trữ đa tầng & phát sóng Realtime 0ms
      if (typeof recordAndSaveNewOrder === "function") {
        recordAndSaveNewOrder(orderObj);
      } else {
        ['mmo_orders', 'mmo_user_orders', 'mmo_all_orders'].forEach(function(k) {
          try {
            let list = JSON.parse(localStorage.getItem(k) || '[]');
            list.unshift(orderObj);
            localStorage.setItem(k, JSON.stringify(list.slice(0, 200)));
          } catch(e) {}
        });
      }

      // Cập nhật giao diện giao hàng
      const dlvId = document.getElementById("dlvOrderId");
      if (dlvId) dlvId.innerText = "#" + orderId;
      const dlvInfo = document.getElementById("dlvProdInfo");
      if (dlvInfo) dlvInfo.innerText = (p.name || "") + (targetVar && targetVar.name && targetVar.name !== "Mặc định" ? " - " + targetVar.name : "");
      const dlvQ = document.getElementById("dlvQty");
      if (dlvQ) dlvQ.innerText = qty + " tài khoản";
      const dlvTot = document.getElementById("dlvTotal");
      if (dlvTot) dlvTot.innerText = formatVND(totalCost);
      const dlvCreds = document.getElementById("dlvCredentials");
      if (dlvCreds) dlvCreds.value = credsText;

      const subtotalVal = unitPrice * qty;
      const discountVal = (window.currentAppliedDiscount > 0) ? Math.round(subtotalVal * window.currentAppliedDiscount / 100) : 0;

      const tyId = document.getElementById("tyOrderId");
      if (tyId) tyId.innerText = "#" + orderId;
      const tyDate = document.getElementById("tyOrderDate");
      if (tyDate) tyDate.innerText = orderObj.date;

      const tySubtotal = document.getElementById("tyOrderSubtotal");
      if (tySubtotal) tySubtotal.innerText = formatVND(subtotalVal);
      const tyDiscount = document.getElementById("tyOrderDiscount");
      if (tyDiscount) tyDiscount.innerText = formatVND(discountVal);
      const tyTot = document.getElementById("tyOrderTotal");
      if (tyTot) tyTot.innerText = formatVND(totalCost);

      const tyStatus = document.getElementById("tyOrderStatus");
      if (tyStatus) {
        tyStatus.innerText = "HOÀN TẤT";
        tyStatus.style.background = "rgba(16,185,129,0.15)";
        tyStatus.style.color = "#10b981";
      }

      const tyProdImg = document.getElementById("tyProdImg");
      if (tyProdImg) {
        tyProdImg.src = p.image || p.image_url || KTS_CLEAN_FALLBACK_SVG;
      }
      const tyProdName = document.getElementById("tyProdName");
      if (tyProdName) tyProdName.innerText = p.name;
      const tyVar = document.getElementById("tyProdVariant");
      if (tyVar) tyVar.innerText = targetVar.name || "Mặc định";
      const tyQty = document.getElementById("tyProdQty");
      if (tyQty) tyQty.innerText = qty;
      const tyProdPrice = document.getElementById("tyProdPrice");
      if (tyProdPrice) tyProdPrice.innerText = formatVND(unitPrice);

      const tySumSubtotal = document.getElementById("tySummarySubtotal");
      if (tySumSubtotal) tySumSubtotal.innerText = formatVND(subtotalVal);
      const tySumDiscount = document.getElementById("tySummaryDiscount");
      if (tySumDiscount) tySumDiscount.innerText = formatVND(discountVal);
      const tySumTotal = document.getElementById("tySummaryTotal");
      if (tySumTotal) tySumTotal.innerText = formatVND(totalCost) + " VND";

      const dlvModal = document.getElementById("orderDeliveryModal");
      if (dlvModal) {
        dlvModal.style.display = "flex";
        dlvModal.style.zIndex = "9999999";
      }

      if (typeof switchView === "function") {
        try {
          switchView("viewThankYou");
          window.scrollTo({ top: 0, behavior: "smooth" });
        } catch(viewErr) {}
      }

      showToast("🎉 Mua hàng thành công! Đã giao " + qty + " tài khoản cho bạn.", "success");
      refreshAllShopStockUI(p.id);

      // Đồng bộ thanh toán trừ tiền ví và đơn hàng lên Google Sheets
      if (typeof callGasApi === "function") {
        callGasApi("payOrderByWallet", {
          email: cleanEmail,
          prodId: p.id,
          prodName: p.name,
          variantName: targetVar.name || "Mặc định",
          quantity: qty,
          orderId: orderId,
          amount: totalCost,
          currentBalance: curBal,
          accounts: credsText
        }).then(res => {
          if (res && res.success && res.newBalance !== undefined) {
            currentUser.balance = Number(res.newBalance);
            localStorage.setItem("mmo_user", JSON.stringify(currentUser));
            let allUsers = getRegisteredUsers();
            const uIdx = allUsers.findIndex(u => (u.email || "").toLowerCase().trim() === cleanEmail);
            if (uIdx !== -1) {
              allUsers[uIdx].balance = Number(res.newBalance);
              saveRegisteredUsers(allUsers);
            }
            updateUserUI();
          }
        }).catch(function() {});
      }
      if (typeof renderUserBalanceLogs === "function") renderUserBalanceLogs();
      if (typeof renderUserWalletTransactions === "function") renderUserWalletTransactions();
    } catch(err) {
      restoreBtn();
      console.error("Lỗi khi mua hàng:", err);
      alert("⚠️ Lỗi xử lý đơn hàng: " + (err && err.message ? err.message : err));
    } finally {
      restoreBtn();
    }
  }
  // =========================================================================
  // [DIRECT INSTANT CHECKOUT & AUTOMATED DELIVERY ENGINE]
  // =========================================================================
  window._pendingDirectOrder = null;

  function openDirectPaymentModal(orderData) {
    const cost = (orderData && orderData.totalCost) ? Number(orderData.totalCost) : 20000;
    const curBal = (currentUser && Number(currentUser.balance)) || 0;
    const missing = Math.max(10000, cost - curBal);
    window._targetDepositAmount = missing;
    showToast("⚠️ Số dư ví không đủ! Đang chuyển hướng sang nạp tiền...", "warning");
    if (typeof closeModal === "function") closeModal("directPaymentModal");
    if (typeof switchView === "function") {
      switchView("viewDeposit");
      if (typeof selectDepositAmount === "function") {
        selectDepositAmount(missing);
      } else if (typeof prepareDeposit === "function") {
        prepareDeposit(missing, true);
      }
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  }
  window.openDirectPaymentModal = openDirectPaymentModal;

  async function handleConfirmDirectPayment() {
    if (!window._pendingDirectOrder) {
      showToast("Không tìm thấy thông tin đơn hàng cần thanh toán!", "warning");
      return;
    }

    const btn = document.getElementById("btnDpConfirmPayment");
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang xuất tài khoản từ kho Turso...";
    }

    const emailInp = document.getElementById("dpModalEmail");
    const buyerEmail = (emailInp ? emailInp.value.trim() : "") || ((typeof currentUser !== "undefined" && currentUser) ? currentUser.email : ("guest_" + Date.now() + "@gmail.com"));

    try {
      await completeOrderDelivery(window._pendingDirectOrder, buyerEmail);
      closeModal("directPaymentModal");
      window._pendingDirectOrder = null;
    } catch(err) {
      showToast("Lỗi giao hàng: " + err.message, "danger");
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = "<i class='fa-solid fa-circle-check'></i> Tôi Đã Thanh Toán &amp; Nhận Tài Khoản";
      }
    }
  }
  window.handleConfirmDirectPayment = handleConfirmDirectPayment;

  async function completeOrderDelivery(orderData, buyerEmail) {
    const { orderId, product, targetVar, vIdx, qty, unitPrice, totalCost, isApiOnDemand, apiMap } = orderData;
    let credsLines = [];

    if (isApiOnDemand) {
      const providerKey = apiMap.provider || "selltainguyenmmo";
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[providerKey]) ? API_SOURCES[providerKey] : { baseUrl: "https://selltainguyenmmo.com", apiKey: "" };
      const buyRes = await executeSourceApiCall("buyProduct", {
        productId: apiMap.sourceProdId,
        amount: qty,
        provider: providerKey,
        baseUrl: apiMap.baseUrl || pCfg.baseUrl,
        apiKey: apiMap.apiKey || pCfg.apiKey,
        username: apiMap.username || pCfg.username,
        password: apiMap.password || pCfg.password,
        targetProdId: product.id
      });
      if (buyRes && buyRes.success && Array.isArray(buyRes.accounts) && buyRes.accounts.length >= qty) {
        credsLines = buyRes.accounts;
      } else {
        throw new Error("Kho hàng đang cập nhật thêm tài khoản mới. Vui lòng thử lại sau!");
      }
    } else {
      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        try {
          const tursoCreds = await TURSO_CLIENT.checkoutAccounts(product.id, vIdx, qty, orderId, buyerEmail, totalCost);
          if (tursoCreds && Array.isArray(tursoCreds) && tursoCreds.length >= qty) {
            credsLines = tursoCreds;
            MMO_WAREHOUSE.deliverAccounts(product.id, vIdx, qty, orderId);
          } else {
            throw new Error("Kho hàng không đủ số lượng tài khoản khả dụng trên máy chủ!");
          }
        } catch(tursoErr) {
          // Failsafe: nếu Turso lỗi mạng hoặc 429, kiểm tra kho MMO_WAREHOUSE nội bộ
          const localCreds = (typeof MMO_WAREHOUSE !== "undefined") ? MMO_WAREHOUSE.deliverAccounts(product.id, vIdx, qty, orderId) : [];
          if (localCreds && Array.isArray(localCreds) && localCreds.length >= qty) {
            credsLines = localCreds;
          } else {
            throw new Error((tursoErr && tursoErr.message) ? tursoErr.message : "Kho hàng không đủ tài khoản khả dụng!");
          }
        }
      } else {
        credsLines = MMO_WAREHOUSE.deliverAccounts(product.id, vIdx, qty, orderId);
      }
    }

    if (!credsLines || credsLines.length < qty) {
      throw new Error("Kho hàng không đủ tài khoản để giao!");
    }

    const credsText = credsLines.join("\n");
    const nowTs = Date.now();
    const formattedNow = (typeof formatOrderDate === "function") ? formatOrderDate(null, nowTs) : new Date().toLocaleString("vi-VN");

    const orderObj = {
      id: orderId,
      orderId: orderId,
      orderCode: orderId,
      userEmail: buyerEmail,
      email: buyerEmail,
      buyerEmail: buyerEmail,
      username: (typeof currentUser !== "undefined" && currentUser ? (currentUser.username || currentUser.name || buyerEmail) : buyerEmail) || "Khách Hàng",
      buyerUsername: (typeof currentUser !== "undefined" && currentUser ? (currentUser.username || currentUser.name || buyerEmail) : buyerEmail) || "Khách Hàng",
      productId: product.id,
      productName: product.name,
      variant: (targetVar && targetVar.name) ? targetVar.name : "Mặc định",
      variantName: (targetVar && targetVar.name) ? targetVar.name : "Mặc định",
      quantity: qty,
      qty: qty,
      price: unitPrice,
      total: totalCost,
      totalPrice: totalCost,
      discount: window.currentAppliedDiscount || 0,
      credentials: credsText,
      deliveredAccounts: credsLines,
      accounts: credsLines,
      createdTimestamp: nowTs,
      createdAt: nowTs,
      date: formattedNow,
      status: "COMPLETED",
      statusText: "Hoàn thành",
      type: "REGULAR"
    };

    if (typeof recordAndSaveNewOrder === "function") {
      recordAndSaveNewOrder(orderObj);
    } else {
      ['mmo_orders', 'mmo_user_orders', 'mmo_all_orders'].forEach(function(k) {
        try {
          let list = JSON.parse(localStorage.getItem(k) || '[]');
          list.unshift(orderObj);
          localStorage.setItem(k, JSON.stringify(list.slice(0, 200)));
        } catch(e) {}
      });
    }

    const dlvCreds = document.getElementById("dlvCredentials");
    if (dlvCreds) dlvCreds.value = credsText;

    const dlvId = document.getElementById("dlvOrderId");
    if (dlvId) dlvId.innerText = "#" + orderId;
    const dlvInfo = document.getElementById("dlvProdInfo");
    if (dlvInfo) dlvInfo.innerText = (product.name || "") + (targetVar && targetVar.name && targetVar.name !== "Mặc định" ? " - " + targetVar.name : "");
    const dlvQ = document.getElementById("dlvQty");
    if (dlvQ) dlvQ.innerText = qty + " tài khoản";
    const dlvTot = document.getElementById("dlvTotal");
    if (dlvTot) dlvTot.innerText = formatVND(totalCost);
    const dlvModal = document.getElementById("orderDeliveryModal");
    if (dlvModal) {
      dlvModal.style.display = "flex";
      dlvModal.style.zIndex = "9999999";
    }

    refreshAllShopStockUI(product.id);
    showToast("🎉 Mua hàng thành công! Đã giao " + credsLines.length + " tài khoản cho bạn.", "success");
    if (typeof addUserNotification === "function") {
      addUserNotification({
        title: "🎉 Mua hàng thành công #" + orderId,
        message: "Bạn đã mua thành công " + credsLines.length + "x " + (product.name || "tài khoản") + ". Đã lưu trữ trong mục Đơn hàng của bạn.",
        type: "ORDER",
        orderId: orderId,
        email: buyerEmail,
        playSound: true
      });
    } else if (typeof playNotificationSound === "function") {
      playNotificationSound();
    }
    return credsLines;
  }
  window.completeOrderDelivery = completeOrderDelivery;

  window.executeBuyCurrentProduct = executeBuyCurrentProduct;
  window.handleDetailBuyAction = executeBuyCurrentProduct;

    function copyDeliveredCreds() {
      const text = document.getElementById("dlvCredentials")?.value || window.lastDeliveredCredentials;
      if (text) {
        copyTextDirect(text);
        showToast("Đã sao chép toàn bộ thông tin tài khoản!", "success");
      }
    }

