    function generateRandomProfile(country, gender) {
      const cData = fakeDataDictionary[country] || fakeDataDictionary.VN;
      let isMale = gender === "MALE" || gender === "male";
      if (gender === "RANDOM" || gender === "random") isMale = Math.random() > 0.5;

      const gStr = isMale ? "Nam (Male)" : "Nữ (Female)";
      const gCode = isMale ? "male" : "female";

      let fullName = "";
      if (country === "VN") {
        const lastName = cData.lastNames[Math.floor(Math.random() * cData.lastNames.length)];
        let middleName = "";
        let firstName = "";
        if (isMale) {
          middleName = cData.middleNamesMale[Math.floor(Math.random() * cData.middleNamesMale.length)];
          firstName = cData.firstNamesMale[Math.floor(Math.random() * cData.firstNamesMale.length)];
        } else {
          middleName = cData.middleNamesFemale[Math.floor(Math.random() * cData.middleNamesFemale.length)];
          firstName = cData.firstNamesFemale[Math.floor(Math.random() * cData.firstNamesFemale.length)];
        }
        fullName = lastName + " " + middleName + " " + firstName;
      } else {
        const fList = isMale ? cData.firstNamesMale : cData.firstNamesFemale;
        const firstName = fList[Math.floor(Math.random() * fList.length)];
        const lastName = cData.lastNames[Math.floor(Math.random() * cData.lastNames.length)];
        fullName = firstName + " " + lastName;
      }

      const y = Math.floor(Math.random() * 25 + 1982);
      const m = String(Math.floor(Math.random() * 12 + 1)).padStart(2, '0');
      const d = String(Math.floor(Math.random() * 28 + 1)).padStart(2, '0');
      const dob = d + "/" + m + "/" + y;

      const cityItem = cData.cities[Math.floor(Math.random() * cData.cities.length)];
      const cityName = (cityItem && typeof cityItem === "object") ? cityItem.city : cityItem;
      const provinceName = (cityItem && typeof cityItem === "object" && cityItem.province) ? cityItem.province : cityName;
      const zipCode = (cityItem && typeof cityItem === "object") ? cityItem.zip : "100000";

      const streetNum = Math.floor(Math.random() * 888 + 12);
      let address = "";
      if (cityItem.locations && cityItem.locations.length > 0) {
        const loc = cityItem.locations[Math.floor(Math.random() * cityItem.locations.length)];
        if (country === "VN") {
          address = streetNum + " " + loc.street + ", " + loc.ward + ", " + loc.district + ", " + provinceName;
        } else {
          address = streetNum + " " + loc.street + (loc.district ? ", " + loc.district : "") + ", " + cityName;
        }
      } else {
        address = streetNum + " Main St, " + cityName;
      }

      const phone = cData.phonePrefix + " " + Math.floor(Math.random() * 8999999 + 1000000);
      const cleanName = fullName.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, "");
      const email = cleanName + y + "@gmail.com";
      const password = cleanName.charAt(0).toUpperCase() + cleanName.slice(1, 6) + "@" + (Math.floor(Math.random() * 899 + 100)) + "!";
      const ip = (Math.floor(Math.random() * 200 + 20)) + "." + (Math.floor(Math.random() * 250 + 1)) + "." + (Math.floor(Math.random() * 250 + 1)) + "." + (Math.floor(Math.random() * 250 + 1));

      return {
        fullName,
        gender: gStr,
        genderCode: gCode,
        dob,
        country,
        address,
        city: cityName,
        zipCode: zipCode,
        phone,
        email,
        password,
        ip
      };
    }

