    function renderSitemapView() {
      const container = document.getElementById("sitemapProductList");
      if (!container) return;
      const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
      container.innerHTML = prods.map(p => {
        return '<div style="border-bottom:1px solid #1e293b; padding-bottom:8px;">' +
          '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" style="color:#e2e8f0; text-decoration:none; font-size:0.85rem; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
            '<span style="font-weight:600;"><i class="fa-solid fa-box" style="color:#10b981; font-size:0.75rem; margin-right:6px;"></i>' + escapeHtml(p.name) + '</span>' +
            '<span style="color:#38bdf8; font-weight:700; white-space:nowrap;">' + formatVND(p.price || 0) + '</span>' +
          '</a>' +
        '</div>';
      }).join("");
    }
    window.renderSitemapView = renderSitemapView;

    // [SEO GOOGLE INDEX]: Tự động khai báo danh mục tất cả sản phẩm dưới dạng Schema ItemList cho Googlebot
function getProductSchemaReviews(p, idx) {
      let customRevs = [];
      try {
        const stored = localStorage.getItem("mmo_product_reviews_" + (p ? p.id : ""));
        if (stored) {
          const parsed = JSON.parse(stored);
          if (Array.isArray(parsed) && parsed.length > 0) customRevs = parsed;
        }
      } catch(e) {}

      const pSold = (p && typeof p.soldCount === "number") ? p.soldCount : 86;
      const ratingCount = Math.max(38, pSold + (((idx || 0) * 7) % 45) + 25);
      const ratingVal = (4.8 + (((idx || 0) * 3) % 3) * 0.1).toFixed(1); // 4.8, 4.9, hoặc 5.0
      const prodName = (p && p.name) ? p.name : "Tài khoản MMO";

      let reviewsList = [];
      if (customRevs.length > 0) {
        reviewsList = customRevs.slice(0, 3).map((r, rIdx) => ({
          "@type": "Review",
          "reviewRating": {
            "@type": "Rating",
            "ratingValue": String(r.rating || 5),
            "bestRating": "5",
            "worstRating": "1"
          },
          "author": {
            "@type": "Person",
            "name": (r.name && !r.name.includes("@")) ? r.name : (r.name ? r.name.split("@")[0] + " (Khách mua)" : "Khách Hàng Xác Thực")
          },
          "datePublished": "2026-09-" + (20 + (rIdx % 8)),
          "reviewBody": r.comment || "Tài khoản chất lượng cao, đúng mô tả, giao hàng tự động siêu tốc."
        }));
      } else {
        reviewsList = [
          {
            "@type": "Review",
            "reviewRating": {
              "@type": "Rating",
              "ratingValue": "5",
              "bestRating": "5",
              "worstRating": "1"
            },
            "author": {
              "@type": "Person",
              "name": "Hoàng Nam (Đã Mua Hàng)"
            },
            "datePublished": "2026-09-25",
            "reviewBody": "Tài khoản " + prodName + " chất lượng rất tốt, đúng mô tả, đăng nhập mượt mà không checkpoint. Ủng hộ shop lâu dài!"
          },
          {
            "@type": "Review",
            "reviewRating": {
              "@type": "Rating",
              "ratingValue": "5",
              "bestRating": "5",
              "worstRating": "1"
            },
            "author": {
              "@type": "Person",
              "name": "Duy Marketing (MMO Pro)"
            },
            "datePublished": "2026-09-22",
            "reviewBody": "Giao hàng tự động trong 5 giây, tài khoản live chuẩn, support nhiệt tình và uy tín số 1."
          },
          {
            "@type": "Review",
            "reviewRating": {
              "@type": "Rating",
              "ratingValue": "5",
              "bestRating": "5",
              "worstRating": "1"
            },
            "author": {
              "@type": "Person",
              "name": "Văn Huy Agency"
            },
            "datePublished": "2026-09-20",
            "reviewBody": "Đã mua nhiều lần bên shop, tài khoản form rất cứng, chế độ bảo hành 1-đổi-1 nhanh chóng nên rất yên tâm."
          }
        ];
      }

      return {
        aggregateRating: {
          "@type": "AggregateRating",
          "ratingValue": String(ratingVal),
          "reviewCount": ratingCount,
          "ratingCount": ratingCount,
          "bestRating": "5",
          "worstRating": "1"
        },
        review: reviewsList
      };
    }
    window.getProductSchemaReviews = getProductSchemaReviews;

    function injectAllProductsSchema() {
      try {
        const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
        if (prods.length === 0) return;
        const deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
        const visibleProds = prods.filter(p => p && p.id && !deletedIds.includes(p.id));
        if (visibleProds.length === 0) return;

        const baseUrl = window.location.origin + window.location.pathname;
        const siteUrl = "https://cuahangcuaban.com/";

        const prodShippingDetails = {
          "@type": "OfferShippingDetails",
          "shippingRate": { "@type": "MonetaryAmount", "value": "0", "currency": "VND" },
          "shippingDestination": { "@type": "DefinedRegion", "addressCountry": "VN" },
          "deliveryTime": {
            "@type": "ShippingDeliveryTime",
            "handlingTime": { "@type": "QuantitativeValue", "minValue": 0, "maxValue": 0, "unitCode": "DAY" },
            "transitTime": { "@type": "QuantitativeValue", "minValue": 0, "maxValue": 0, "unitCode": "DAY" }
          }
        };
        const prodReturnPolicy = {
          "@type": "MerchantReturnPolicy",
          "applicableCountry": "VN",
          "returnPolicyCategory": "https://schema.org/MerchantReturnFiniteReturnWindow",
          "merchantReturnDays": 1,
          "returnMethod": "https://schema.org/ReturnByMail",
          "returnFees": "https://schema.org/FreeReturn"
        };

        // Kiểm tra xem có đang ở trang chi tiết sản phẩm cụ thể hay không
        const urlParams = new URLSearchParams(window.location.search);
        const targetProdId = urlParams.get("prod") || urlParams.get("product") || (window.location.hash && window.location.hash.startsWith("#product_") ? window.location.hash.replace("#product_", "") : null);

        if (targetProdId) {
          // Xóa schema danh sách cũ nếu có
          const s = document.getElementById("schemaAllProductsItemList");
          if (s) s.remove();

          // Tìm sản phẩm cụ thể để tạo Schema Product độc lập hoàn hảo 100%
          const curP = visibleProds.find(item => item && (String(item.id) === String(targetProdId) || String(item.id).toLowerCase() === String(targetProdId).toLowerCase())) || visibleProds[0];
          if (curP) {
            let detailScriptEl = document.getElementById("schemaSingleProductDetail");
            if (!detailScriptEl) {
              detailScriptEl = document.createElement("script");
              detailScriptEl.id = "schemaSingleProductDetail";
              detailScriptEl.type = "application/ld+json";
              document.head.appendChild(detailScriptEl);
            }
            const prodUrl = baseUrl + "/search?q=" + encodeURIComponent(curP.id);
            const price = (curP.variants && curP.variants[0] && curP.variants[0].price) ? curP.variants[0].price : (curP.price || 0);
            const imgUrl = (typeof resolveProductSeoSchemaImage === "function") ? resolveProductSeoSchemaImage(curP) : ((curP.image && !curP.image.startsWith("data:")) ? curP.image : KTS_CLEAN_FALLBACK_SVG);
            const ratingData = getProductSchemaReviews(curP, 0);

            const singleProdSchema = {
              "@context": "https://schema.org",
              "@type": "Product",
              "@id": prodUrl + "#product",
              "name": curP.name,
              "description": (curP.description || ("Mua " + curP.name + " tự động 24/7 uy tín, giá rẻ nhất Việt Nam.")).slice(0, 300),
              "url": prodUrl,
              "image": [imgUrl],
              "sku": curP.id,
              "mpn": curP.id,
              "identifier_exists": "false",
              "brand": { "@type": "Brand", "name": "KHO TÀI KHOẢN SỐ" },
              "category": curP.category || "Tài Khoản MMO",
              "offers": {
                "@type": "Offer",
                "url": prodUrl,
                "priceCurrency": "VND",
                "price": price,
                "priceValidUntil": "2027-12-31",
                "validFrom": "2026-01-01",
                "availability": (curP.stock > 0) ? "https://schema.org/InStock" : "https://schema.org/OutOfStock",
                "itemCondition": "https://schema.org/NewCondition",
                "seller": { "@type": "Organization", "name": "KHO TÀI KHOẢN SỐ" },
                "shippingDetails": prodShippingDetails,
                "hasMerchantReturnPolicy": prodReturnPolicy
              },
              "aggregateRating": ratingData.aggregateRating,
              "review": ratingData.review
            };
            detailScriptEl.textContent = JSON.stringify(singleProdSchema);
            return;
          }
        }

        // Nếu ở trang chủ / danh mục: Tạo ItemList chứa toàn bộ sản phẩm kèm AggregateRating & Review
        let listDetailEl = document.getElementById("schemaSingleProductDetail");
        if (listDetailEl) listDetailEl.remove();

        let scriptEl = document.getElementById("schemaAllProductsItemList");
        if (!scriptEl) {
          scriptEl = document.createElement("script");
          scriptEl.id = "schemaAllProductsItemList";
          scriptEl.type = "application/ld+json";
          document.head.appendChild(scriptEl);
        }

        const graphSchema = {
          "@context": "https://schema.org",
          "@graph": [
            {
              "@type": "WebSite",
              "@id": siteUrl + "#website",
              "url": siteUrl,
              "name": "KHO TÀI KHOẢN SỐ",
              "description": "He thong mua ban tai khoan mang xa hoi, cong cu MMO, proxy tu dong 24/7 uy tin so 1 Viet Nam",
              "publisher": { "@id": siteUrl + "#organization" }
            },
            {
              "@type": "Organization",
              "@id": siteUrl + "#organization",
              "name": "KHO TÀI KHOẢN SỐ",
              "url": siteUrl,
              "logo": { "@type": "ImageObject", "url": KTS_CLEAN_FALLBACK_SVG }
            },
            {
              "@type": "ItemList",
              "@id": siteUrl + "#productlist",
              "name": "Danh Sach San Pham Tai Khoan MMO - khotaikhoanso.net",
              "numberOfItems": visibleProds.length,
              "itemListElement": visibleProds.map((p, idx) => {
                const prodUrl = baseUrl + "/search?q=" + encodeURIComponent(p.id);
                const price = (p.variants && p.variants[0] && p.variants[0].price) ? p.variants[0].price : (p.price || 0);
                const imgUrl = (typeof resolveProductSeoSchemaImage === "function") ? resolveProductSeoSchemaImage(p) : ((p.image && !p.image.startsWith("data:")) ? p.image : KTS_CLEAN_FALLBACK_SVG);
                const ratingData = getProductSchemaReviews(p, idx);
                return {
                  "@type": "ListItem",
                  "position": idx + 1,
                  "item": {
                    "@type": "Product",
                    "@id": prodUrl + "#product",
                    "name": p.name,
                    "description": (p.description || ("Mua " + p.name + " tu dong 24/7 uy tin, gia re nhat Viet Nam.")).slice(0, 300),
                    "url": prodUrl,
                    "image": [imgUrl],
                    "sku": p.id,
                    "mpn": p.id,
                    "identifier_exists": "false",
                    "brand": { "@type": "Brand", "name": "KHO TÀI KHOẢN SỐ" },
                    "category": p.category || "Tai Khoan MMO",
                    "offers": {
                      "@type": "Offer",
                      "url": prodUrl,
                      "priceCurrency": "VND",
                      "price": price,
                      "priceValidUntil": "2027-12-31",
                      "validFrom": "2026-01-01",
                      "availability": (p.stock > 0) ? "https://schema.org/InStock" : "https://schema.org/OutOfStock",
                      "itemCondition": "https://schema.org/NewCondition",
                      "seller": { "@type": "Organization", "name": "KHO TÀI KHOẢN SỐ" },
                      "shippingDetails": prodShippingDetails,
                      "hasMerchantReturnPolicy": prodReturnPolicy
                    },
                    "aggregateRating": ratingData.aggregateRating,
                    "review": ratingData.review
                  }
                };
              })
            }
          ]
        };
        scriptEl.textContent = JSON.stringify(graphSchema);
      } catch(e) { console.warn("injectAllProductsSchema error:", e); }
    }
    window.injectAllProductsSchema = injectAllProductsSchema;

    // SEO CHUM: Render related products widget
    function renderRelatedProductsSeo(currentProduct) {
      try {
        const container = document.getElementById("dtlSeoRelatedProducts");
        if (!container) return;
        const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
        const deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
        const related = prods.filter(p =>
          p && p.id && p.id !== currentProduct.id &&
          !deletedIds.includes(p.id) &&
          p.category === currentProduct.category
        ).slice(0, 6);

        if (related.length === 0) { container.style.display = "none"; return; }
        container.style.display = "block";
        const baseUrl = window.location.origin + window.location.pathname;
        const relItems = related.map(rp => {
          const rpUrl = baseUrl + "?prod=" + encodeURIComponent(rp.id) + "&view=viewProductDetail";
          const rpPrice = (rp.variants && rp.variants[0] && rp.variants[0].price) ? rp.variants[0].price : (rp.price || 0);
          const rpStock = (typeof getProductStockCount === "function") ? getProductStockCount(rp) : (rp.stock || 0);
          const rpPriceStr = (typeof formatVND === "function") ? formatVND(rpPrice) : rpPrice.toLocaleString("vi-VN") + "d";
          const eName = (typeof escapeHtml === "function") ? escapeHtml(rp.name) : rp.name.replace(/</g,"&lt;").replace(/>/g,"&gt;");
          return '<a href="' + rpUrl + '" onclick="event.preventDefault(); openProductDetailById(\'' + rp.id + '\')" '
            + 'style="display:block; background:#0d121f; border:1px solid #1e293b; border-radius:8px; padding:8px; text-decoration:none;" '
            + 'rel="noopener" title="' + eName + '">'
            + '<img src="' + (rp.image || KTS_CLEAN_FALLBACK_SVG) + '" alt="' + eName + '" '
            + 'style="width:100%; height:70px; object-fit:cover; border-radius:5px; margin-bottom:6px;" loading="lazy"/>'
            + '<div style="font-size:0.72rem; color:#cbd5e1; line-height:1.3; margin-bottom:4px;">' + eName + '</div>'
            + '<div style="font-size:0.75rem; color:#10b981; font-weight:700;">' + rpPriceStr + '</div>'
            + '<div style="font-size:0.65rem; color:' + (rpStock > 0 ? '#10b981' : '#ef4444') + ';">' + (rpStock > 0 ? 'Con hang' : 'Het hang') + '</div>'
            + '</a>';
        }).join("");
        container.innerHTML = '<div style="margin-top:20px; border-top:1px solid #1e293b; padding-top:16px;">'
          + '<h3 style="font-size:0.92rem; color:#38bdf8; margin-bottom:12px; display:flex; align-items:center; gap:6px;">'
          + '<i class="fa-solid fa-layer-group"></i> San Pham Lien Quan</h3>'
          + '<div style="display:grid; grid-template-columns:repeat(auto-fill,minmax(140px,1fr)); gap:8px;">'
          + relItems + '</div></div>';
      } catch(e) {}
    }
    window.renderRelatedProductsSeo = renderRelatedProductsSeo;



