    // ĐỒNG BỘ TIN NHẮN TỪ CLOUD / BACKEND GOOGLE SHEETS
    var _isSyncingCloudChat = false;
    var _lastChatSyncTimestamp = 0;

    async function syncCloudMessages(isSilent = false) {
      if (_isSyncingCloudChat) return;
      const isAdm = typeof isAdminUser === "function" && isAdminUser();
      const myEmail = getCurrentChatUserEmail();
      _isSyncingCloudChat = true;

      try {
        let synced = false;
        const workerApi = (typeof window !== "undefined" && window.MMO_SHOP_CONFIG && window.MMO_SHOP_CONFIG.WORKER_API_URL) || "https://mmo-shop-api.khotaikhoanso-net.workers.dev";
        const workerChatUrl = workerApi + "/api/chat/messages" + (isAdm ? "" : ("?userEmail=" + encodeURIComponent(myEmail)));

        // 1. Kéo cực nhanh từ Cloudflare Worker Turso SSOT (<50ms)
        try {
          const res = await fetch(workerChatUrl, {
            headers: { "Accept": "application/json" }
          });
          if (res.ok) {
            const data = await res.json();
            if (data && data.success && Array.isArray(data.messages)) {
              mergeIncomingMessages(data.messages, !isSilent);
              synced = true;
            }
          }
        } catch(workerErr) {}

        // 2. Kéo từ Google Sheets GAS (Nếu chưa lấy được từ Worker)
        if (!synced && typeof callGasApi === "function") {
          try {
            const gasRes = await callGasApi("getChatMessages", isAdm ? {} : { userEmail: myEmail });
            if (gasRes && gasRes.success && Array.isArray(gasRes.messages)) {
              mergeIncomingMessages(gasRes.messages, !isSilent);
            }
          } catch(gasErr) {}
        }
      } catch(err) {
        console.warn("syncCloudMessages error:", err);
      } finally {
        _isSyncingCloudChat = false;
        _lastChatSyncTimestamp = Date.now();
      }
    }
    window.syncCloudMessages = syncCloudMessages;

    function triggerFastChatSync() {
      syncCloudMessages(true);
    }
    window.triggerFastChatSync = triggerFastChatSync;

    function mergeIncomingMessages(incomingList, playSoundOnNew = true) {
      if (!incomingList || !incomingList.length) return;
      const allMsgs = getAllChatMessages();
      const idMap = new Set(allMsgs.map(m => m.id));
      let hasChange = false;
      let hasNewUserMsg = false;
      let hasNewAdminMsg = false;
      const isAdm = typeof isAdminUser === "function" && isAdminUser();
      const myEmail = getCurrentChatUserEmail();

      incomingList.forEach(function(item) {
        if (!item || !item.id || (!item.text && !item.imageUrl)) return;
        if (idMap.has(item.id)) return;

        if (!item.imageUrl) {
          item.imageUrl = extractChatImageUrl(item);
        }

        idMap.add(item.id);
        allMsgs.push(item);
        hasChange = true;

        if (item.sender === "user") {
          hasNewUserMsg = true;
        } else if (item.sender === "admin" && item.userEmail === myEmail) {
          hasNewAdminMsg = true;
        }
      });

      if (hasChange) {
        saveAllChatMessages(allMsgs);
        updateChatUnreadBadge();

        if (isAdm) {
          renderAdminChatList();
          if (currentAdminChatTargetEmail) {
            renderAdminActiveStream(currentAdminChatTargetEmail);
          }
          if (hasNewUserMsg && playSoundOnNew) {
            playChatNotificationSound("receive");
            const newest = incomingList.slice().reverse().find(m => m && m.sender === "user");
            if (newest && typeof showToast === "function") {
              const who = newest.senderName || newest.userEmail;
              const snip = newest.text.length > 35 ? (newest.text.slice(0, 35) + "...") : newest.text;
              showToast("🔔 Khách hàng " + who + " vừa nhắn: '" + snip + "'", "info");
            }
          }
        } else {
          renderChatMessageList();
          if (hasNewAdminMsg && playSoundOnNew) {
            playChatNotificationSound("receive");
          }
        }
      }
    }


