window.switchAiWritingMode = switchAiWritingMode;

function openAiWriterModal() {
  const modal = document.getElementById('aiWriterModal');
  if (modal) { modal.style.setProperty('display', 'flex', 'important'); document.body.style.overflow = 'hidden'; }
  let savedPKey = localStorage.getItem('mmo_ai_selected_provider');
  
  // Ưu tiên số 1 luôn là Groq nếu có key hoặc nếu savedPKey là gemini nhưng gemini không có key riêng
  const hasGroqKey = !!MMO_AI_KEYS.get('groq');
  if (hasGroqKey && (!savedPKey || savedPKey === 'gemini' || !MMO_AI_KEYS.get(savedPKey))) {
    savedPKey = 'groq';
    try { localStorage.setItem('mmo_ai_selected_provider', 'groq'); } catch(e) {}
  } else if (!savedPKey || !MMO_AI_KEYS.get(savedPKey)) {
    const _aiProviders = ['groq', 'openrouter', 'cerebras', 'gemini', 'mistral', 'nvidia'];
    const withKey = _aiProviders.find(p => !!MMO_AI_KEYS.get(p));
    savedPKey = withKey || 'groq';
  }
  const pSel = document.getElementById('aiProviderSelect');
  if (pSel) { pSel.value = savedPKey; }
  onAiProviderChange();
  const savedMode = localStorage.getItem('mmo_ai_writer_mode') || 'keyword';
  switchAiWritingMode(savedMode);
  if (window.innerWidth <= 900) {
    switchAiMobileTab('config');
  } else {
    const modalBody = document.querySelector('#aiWriterModal .ai-modal-body');
    if (modalBody && modalBody.children.length >= 2) {
      modalBody.children[0].style.display = '';
      modalBody.children[1].style.display = '';
    }
  }
}

function closeAiWriterModal() {
  const modal = document.getElementById('aiWriterModal');
  if (modal) { modal.style.setProperty('display', 'none', 'important'); document.body.style.overflow = ''; }
}

function updateAiMetaCounter() {
  const meta = document.getElementById('aiSeoMeta');
  const counter = document.getElementById('aiMetaCounter');
  if (!meta || !counter) return;
  const len = meta.value.length;
  counter.textContent = '(' + len + '/160)';
  counter.style.color = len > 155 ? '#22c55e' : len > 120 ? '#f59e0b' : '#64748b';
}

function applyAiCmd(cmd, val) {
  const el = document.getElementById('aiEditorContent');
  if (!el) return;
  el.focus();
  if (val !== undefined && val !== null) {
    document.execCommand(cmd, false, val);
  } else {
    document.execCommand(cmd, false, null);
  }
}

function clearAiEditor() {
  const el = document.getElementById('aiEditorContent');
  if (el && confirm('Xóa toàn bộ nội dung bài viết?')) el.innerHTML = '';
}

function onAiEditorInput() {
  const el = document.getElementById('aiEditorContent');
  if (!el) return;
  if (el.innerHTML === '' || el.innerHTML === '<br>') {
    el.setAttribute('data-empty', 'true');
  } else {
    el.removeAttribute('data-empty');
  }
}

async function callAiChatService(pKey, modelId, promptText, sysPrompt, maxTokens = 4096) {
  const prov = AI_PROVIDERS[pKey] || AI_PROVIDERS.groq;
  let apiKey = MMO_AI_KEYS.get(pKey);
  if (!apiKey) {
    throw new Error('Chưa có API Key cho ' + prov.name + '. Vui lòng bấm link bên dưới lấy key miễn phí và bấm Lưu!');
  }

  // Tự động sửa model cũ của Groq nếu bị lỗi thời
  let targetModel = modelId || prov.defaultModel;
  if (pKey === 'groq') {
    const validGroqModels = ['qwen/qwen3.8-27b', 'openai/gpt-oss-120b', 'openai/gpt-oss-20b'];
    if (!validGroqModels.includes(targetModel)) {
      targetModel = 'qwen/qwen3.8-27b';
    }
  }

  const effectiveMaxTokens = Math.min(maxTokens || 8192, 8192);

  if (prov.isOpenAiFormat) {
    const headers = {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + apiKey
    };
    if (prov.extraHeaders) Object.assign(headers, prov.extraHeaders);
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000);
    let res;
    try {
      res = await fetch(prov.endpoint, {
        method: 'POST',
        headers: headers,
        signal: controller.signal,
        body: JSON.stringify({
          model: targetModel,
          messages: [
            { role: 'system', content: sysPrompt || 'Bạn là chuyên gia SEO Content Writer tiếng Việt hàng đầu.' },
            { role: 'user', content: promptText }
          ],
          temperature: 0.7,
          max_tokens: effectiveMaxTokens
        })
      });
    } catch(fetchErr) {
      clearTimeout(timeoutId);
      throw new Error(prov.name + ' kết nối bị gián đoạn hoặc quá hạn: ' + fetchErr.message);
    }
    clearTimeout(timeoutId);

    // Tự động thử lại với Qwen 3.8 27B nếu Groq trả về 404 model not found
    if (pKey === 'groq' && !res.ok && res.status === 404 && targetModel !== 'qwen/qwen3.8-27b') {
      console.warn('Groq model ' + targetModel + ' trả về 404, tự động chuyển sang qwen/qwen3.8-27b...');
      return await callAiChatService('groq', 'qwen/qwen3.8-27b', promptText, sysPrompt, maxTokens);
    }

    if (!res.ok) {
      const errText = await res.text();
      // XỬ LÝ THÔNG MINH CHO LỖI 429 RATE LIMIT HOẶC HẾT QUOTA
      if (res.status === 429) {
        if (pKey === 'mistral' && modelId !== 'open-mistral-7b') {
          // Tự động thử lại với model nhẹ hơn open-mistral-7b sau 1.2s
          try {
            await new Promise(r => setTimeout(r, 1200));
            const retryRes = await fetch(prov.endpoint, {
              method: 'POST',
              headers: headers,
              body: JSON.stringify({
                model: 'open-mistral-7b',
                messages: [
                  { role: 'system', content: sysPrompt || 'Bạn là chuyên gia SEO Content Writer tiếng Việt hàng đầu.' },
                  { role: 'user', content: promptText }
                ],
                temperature: 0.7,
                max_tokens: 2048
              })
            });
            if (retryRes.ok) {
              const retryJson = await retryRes.json();
              const rReply = retryJson.choices && retryJson.choices[0] && retryJson.choices[0].message ? retryJson.choices[0].message.content : '';
              if (rReply) return rReply;
            }
          } catch(e) {}
        }
        throw new Error(prov.name + ' Error 429 (Hết Quota/Vượt giới hạn Free): Tài khoản của bạn đã đạt hạn mức truy vấn. Hãy đổi sang ⚡ Groq (Llama 3.3 70B) hoặc 🤖 Google Gemini để viết bài miễn phí siêu tốc!');
      }
      throw new Error(prov.name + ' Error ' + res.status + ': ' + errText.slice(0, 220));
    }
    const json = await res.json();
    const reply = json.choices && json.choices[0] && json.choices[0].message ? json.choices[0].message.content : '';
    if (!reply) throw new Error(prov.name + ' không phản hồi nội dung.');
    return reply;
  } else {
    let targetModels = [];
    if (modelId) {
      let m = modelId;
      if (m.includes('pro-latest')) m = 'gemini-1.5-pro';
      targetModels.push(m);
    }
    const fallbackList = ['gemini-2.5-flash', 'gemini-2.0-flash', 'gemini-1.5-flash', 'gemini-1.5-pro'];
    for (const fb of fallbackList) {
      if (!targetModels.includes(fb)) targetModels.push(fb);
    }

    let lastErrText = '';
    for (const curModel of targetModels) {
      try {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${curModel}:generateContent?key=${apiKey}`;
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 20000);
        const res = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          signal: controller.signal,
          body: JSON.stringify({
            contents: [{ parts: [{ text: (sysPrompt ? sysPrompt + "\n\n" : "") + promptText }] }],
            generationConfig: { maxOutputTokens: effectiveMaxTokens, temperature: 0.7 }
          })
        });
        clearTimeout(timeoutId);
        if (res.ok) {
          const json = await res.json();
          const reply = json.candidates && json.candidates[0] && json.candidates[0].content && json.candidates[0].content.parts && json.candidates[0].content.parts[0] ? json.candidates[0].content.parts[0].text : '';
          if (reply) return reply;
        } else {
          const errBody = await res.text();
          lastErrText = errBody;
          if (res.status === 429) {
            throw new Error('Gemini Quota Exceeded (429): Quota Gemini của bạn đã hết. Vui lòng bấm nút đổi sang ⚡ Groq để viết bài siêu tốc miễn phí!');
          }
          if (res.status === 403 || errBody.includes('leaked') || errBody.includes('PERMISSION_DENIED') || errBody.includes('API_KEY_INVALID')) {
            throw new Error('Gemini API Key không hợp lệ hoặc đã bị khóa/hết hạn. Vui lòng đổi sang ⚡ Groq (Khuyên dùng - 3 giây) để viết bài ngay!');
          }
        }
      } catch(eCur) {
        if (eCur.message && (eCur.message.includes('Quota') || eCur.message.includes('không hợp lệ') || eCur.message.includes('Groq'))) {
          throw eCur;
        }
        lastErrText = eCur.message;
      }
    }
    throw new Error('Gemini Error: ' + (lastErrText ? lastErrText.slice(0, 220) : 'Tất cả model Gemini đều không phản hồi. Vui lòng bấm đổi sang ⚡ Groq để viết bài ngay!'));
  }
}

async function autoSuggestKeywordsOnly() {
  const topicEl = document.getElementById('aiTopic');
  const kwInput = document.getElementById('aiKeywords');
  let topic = (topicEl || {}).value || '';
  let curKw = (kwInput || {}).value || '';

  if (!topic.trim() && curKw.trim()) {
    topic = curKw.trim().split(',')[0].trim();
    if (topicEl) topicEl.value = topic;
  }

  if (!topic.trim()) {
    showToast('⚠️ Vui lòng nhập Tiêu Đề hoặc Từ Khóa trước khi bấm Gợi ý!', 'warn');
    if (topicEl) topicEl.focus();
    return;
  }
  const statusEl = document.getElementById('aiGenerateStatus');
  const pSel = document.getElementById('aiProviderSelect');
  const mSel = document.getElementById('aiModelSelect');
  const pKey = pSel ? pSel.value : 'groq';
  const modelId = mSel ? mSel.value : '';

  if (statusEl) statusEl.innerHTML = '<span style="color:#a855f7;">⏳ Đang phân tích từ khóa SEO tối ưu...</span>';
  try {
    const prompt = `Phân tích chủ đề sau: "${topic}". Hãy trích xuất và đề xuất bộ 3-5 từ khóa SEO quan trọng nhất (bao gồm 1 từ khóa chính và 2-4 từ khóa phụ LSI liên quan chặt chẽ), phân cách bằng dấu phẩy. Chỉ trả về các từ khóa phân cách bằng dấu phẩy, không thêm bất kỳ lời dẫn hay dấu ngoặc nào.`;
    const resText = await callAiChatService(pKey, modelId, prompt, "Bạn là chuyên gia nghiên cứu từ khóa SEO Google tiếng Việt.");
    const cleaned = resText.replace(/^[\r\n\s]+|[\r\n\s]+$/g, '').replace(/^(Từ khóa|Keywords):\s*/i, '');
    if (kwInput) {
      kwInput.value = cleaned;
      kwInput.setAttribute('data-auto-generated', 'true');
    }
    if (statusEl) statusEl.innerHTML = '<span style="color:#22c55e;">✅ Đã gợi ý từ khóa SEO thành công!</span>';
    showToast('✨ Đã gợi ý từ khóa SEO!', 'success');
  } catch (err) {
    console.error('Keyword suggest error:', err);
    if (statusEl) statusEl.innerHTML = '<span style="color:#f87171;">❌ ' + (err.message || 'Lỗi gợi ý') + '</span>';
    showToast('❌ Lỗi: ' + (err.message || 'Không thể gợi ý từ khóa'), 'error');
  }
}

function convertMarkdownToCleanHtml(str) {
  if (!str) return '';
  let s = str.trim();
  s = s.replace(/^`{3}(html)?\s*/i, '').replace(/`{3}\s*$/i, '').trim();
  s = s.replace(/^(Chào bạn|Dưới đây là|Sau đây là|Đây là bài viết|Tuyệt vời|Dưới đây là nội dung)[^\n]*\n+/i, '');
  s = s.replace(/\*\*\*([^*]+)\*\*\*/g, '<strong><em>$1</em></strong>');
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  s = s.replace(/__([^_]+)__/g, '<strong>$1</strong>');
  s = s.replace(/(^|[^\*])\*([^\*\n]+)\*([^\*]|$)/g, '$1<em>$2</em>$3');
  s = s.replace(/([^\n])\s+##\s+/g, '$1\n\n## ');
  s = s.replace(/([^\n])\s+###\s+/g, '$1\n\n### ');
  s = s.replace(/([^\n])\s+\*\s+\*\*/g, '$1\n* **');
  s = s.replace(/([^\n])\s+-\s+\*\*/g, '$1\n- **');

  // Tách các bảng bị dồn trên 1 dòng có nhiều cặp || (ví dụ: | Yêu cầu | Chi tiết ||---|...|)
  s = s.replace(/\|\s*\|+/g, '|\n|');

  // Tách các mục ghim 📌, 📍, 🎯, 👉, ✅, ⚡, 🔹, 🔸 nếu bị dồn sau văn bản hoặc cùng trên 1 dòng
  s = s.replace(/([^\n])\s*(📌|📍|🎯|👉|✅|⚡|🔹|🔸)/g, '$1\n$2');

  // Loại bỏ hoàn toàn các dòng kẻ ---, ***, ___
  s = s.replace(/^[ \t]*[-*_]{3,}[ \t]*$/gm, '');

  const lines = s.split(/\r?\n/);
  const out = [];
  let inList = null;
  let currentP = [];
  function flushP() {
    if (currentP.length > 0) {
      const text = currentP.join(' ').trim();
      if (text) {
        if (/^<(div|blockquote|table|h[1-6]|p)/i.test(text)) {
          out.push(text);
        } else {
          out.push('<p>' + text + '</p>');
        }
      }
      currentP = [];
    }
  }
  function flushList() {
    if (inList) {
      out.push('</' + inList + '>');
      inList = null;
    }
  }
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i].trim();
    if (!line) {
      flushP(); flushList(); continue;
    }

    // Bỏ qua dòng gạch ngang ---, ***, ___
    if (/^[-*_]{3,}$/.test(line)) {
      flushP(); flushList(); continue;
    }

    // Bắt và chuyển đổi bảng Markdown Table thành HTML Table chuẩn đẹp
    if (line.startsWith('|') && line.endsWith('|')) {
      flushP(); flushList();
      const tableLines = [line];
      while (i + 1 < lines.length && lines[i + 1].trim().startsWith('|') && lines[i + 1].trim().endsWith('|')) {
        i++;
        tableLines.push(lines[i].trim());
      }
      if (tableLines.length >= 2) {
        let hasSeparator = false;
        let headerCols = [];
        const bodyRows = [];
        for (let r = 0; r < tableLines.length; r++) {
          const rawRow = tableLines[r];
          const cells = rawRow.split('|').slice(1, -1).map(function(c) { return c.trim(); });
          if (r === 1 && cells.every(function(c) { return /^[:\- ]+$/.test(c); })) {
            hasSeparator = true;
            continue;
          }
          if (r === 0) {
            headerCols = cells;
          } else {
            bodyRows.push(cells);
          }
        }
        if (hasSeparator || headerCols.length > 0) {
          let tblHtml = '<div style="overflow-x:auto; margin:18px 0;">\n  <table style="width:100%; border-collapse:collapse; text-align:left; font-size:14px; border:1px solid #cbd5e1; border-radius:8px; overflow:hidden;">\n';
          if (headerCols.length > 0) {
            tblHtml += '    <thead>\n      <tr style="background:#1e293b; color:#ffffff;">\n';
            headerCols.forEach(function(h) {
              tblHtml += '        <th style="padding:12px 14px; border:1px solid #334155; font-weight:700;">' + h + '</th>\n';
            });
            tblHtml += '      </tr>\n    </thead>\n';
          }
          tblHtml += '    <tbody>\n';
          bodyRows.forEach(function(row, rIdx) {
            const bg = (rIdx % 2 === 0) ? '#f8fafc' : '#ffffff';
            tblHtml += '      <tr style="background:' + bg + '; border-bottom:1px solid #e2e8f0;">\n';
            row.forEach(function(c) {
              tblHtml += '        <td style="padding:10px 14px; border:1px solid #cbd5e1; color:#1e293b;">' + c + '</td>\n';
            });
            tblHtml += '      </tr>\n';
          });
          tblHtml += '    </tbody>\n  </table>\n</div>';
          out.push(tblHtml);
          continue;
        }
      }
    }

    // Bắt các mục ghim (📌, 📍, 🎯, 👉, ✅, ⚡, 🔹, 🔸) xuống dòng và đặt icon ghim ở đầu dòng
    const pinMatch = line.match(/^(📌|📍|🎯|👉|✅|⚡|🔹|🔸)\s*(.+)$/);
    if (pinMatch) {
      flushP(); flushList();
      const icon = pinMatch[1];
      let itemContent = pinMatch[2].trim();
      const colonIdx = itemContent.indexOf(':');
      if (colonIdx > 0 && colonIdx < 40 && !itemContent.includes('<strong>')) {
        const prefix = itemContent.slice(0, colonIdx).trim();
        const suffix = itemContent.slice(colonIdx + 1).trim();
        itemContent = '<strong>' + prefix + ':</strong> ' + suffix;
      }
      out.push('<p style="margin:8px 0; padding-left:4px; line-height:1.6;"><span style="font-size:16px;">' + icon + '</span> ' + itemContent + '</p>');
      continue;
    }

    const h4Match = line.match(/^####\s+(.+)$/);
    if (h4Match) { flushP(); flushList(); out.push("<h4>" + h4Match[1].trim() + "</h4>"); continue; }
    const h3Match = line.match(/^###\s+(.+)$/);
    if (h3Match) { flushP(); flushList(); out.push("<h3>" + h3Match[1].trim() + "</h3>"); continue; }
    const h2Match = line.match(/^##?\s+(.+)$/);
    if (h2Match) { flushP(); flushList(); out.push("<h2>" + h2Match[1].trim() + "</h2>"); continue; }
    if (line.startsWith('>')) { flushP(); flushList(); out.push('<blockquote>' + line.replace(/^>\s*/, '').trim() + '</blockquote>'); continue; }
    const olMatch = line.match(/^[0-9]+\.\s+(.+)$/);
    if (olMatch) {
      flushP();
      if (inList !== 'ol') { flushList(); out.push('<ol>'); inList = 'ol'; }
      out.push('  <li>' + olMatch[1].trim() + '</li>');
      continue;
    }
    const ulMatch = line.match(/^[\*\-•]\s+(.+)$/);
    if (ulMatch) {
      flushP();
      if (inList !== 'ul') { flushList(); out.push('<ul>'); inList = 'ul'; }
      out.push('  <li>' + ulMatch[1].trim() + '</li>');
      continue;
    }
    if (/^<(h[1-6]|ul|ol|div|blockquote|table|p)/i.test(line)) {
      flushP(); flushList(); out.push(line); continue;
    }
    flushList();
    currentP.push(line);
  }
  flushP(); flushList();
  let html = out.join('\n');
  html = html.replace(/<p>\s*[-*_]{2,}\s*<\/p>/gi, '');
  html = html.replace(/#{2,6}\s*/g, '');
  html = html.replace(/\*{2,3}/g, '');
  return html;
}

function extractTitleFromUrl(rawUrl) {
  try {
    const u = new URL(rawUrl);
    let path = decodeURIComponent(u.pathname || '').replace(/\/+$/, '');
    let parts = path.split('/').filter(p => p && !/^(tin-tuc|thu-thuat|blog|post|posts|bai-viet|article|articles|news|category|tag|wiki|news-detail|detail|amp|view)$/i.test(p));
    let slug = parts.pop() || '';
    slug = slug.replace(/\.[a-zA-Z0-9]+$/, '');
    slug = slug.replace(/[-_]?(post|id)?\d{4,}$/i, '');
    slug = slug.replace(/[-_]+/g, ' ').trim();
    if (!slug) return '';
    return slug.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  } catch(e) {
    return '';
  }
}

function isCloudflareChallenge(str) {
  if (!str || typeof str !== 'string') return false;
  const s = str.toLowerCase();
  return s.includes('attention required') || s.includes('just a moment') || s.includes('cloudflare') || 
         s.includes('security verification') || s.includes('captcha') || s.includes('access denied') || 
         s.includes('403 forbidden') || s.includes('error 1027') || s.includes('rate limit');
}

