    // ============================================================
    const verifyLower = rawText.toLowerCase();
    const needFaq = !verifyLower.includes('faq') && !verifyLower.includes('câu hỏi thường gặp') && !verifyLower.includes('thường gặp');
    const needConclusion = !verifyLower.includes('lời kết') && !verifyLower.includes('kết luận') && !verifyLower.includes('bước tiếp theo');

